programs.sol:
"""Sparse responses to short collocations and split compound words.

English peaks occur in 'all about/around', wrapping or turning around,
physical contact, and round/on-table combinations.  Other modes recognize
particular Korean/Japanese words, and Chinese totality, changes of level,
rotation and transformation. Dictionary-recognized institutional and linking
compounds have a negative response. These are separate lexical modes, not a claim
that the component recognizes one topic. Unmatched positions predict zero,
with small offsets for document openings and doubled middle dots.
"""
import re
from functools import lru_cache
import regex
import wordnet
import cedict
import jmdict

READS = ()

# Explicit lexical modes; values apply only when a token finishes a split word.
WORDS = {
    "안전": 4.3,       # safety
    "연주": 3.7,       # musical performance
    "반영": -3.5,      # reflection
    "반면": -4.2,      # conversely
    "반부": -4.3,      # anti- (as in anti-corruption)
    "반전": 4.3,       # reversal
    "원천": 4.5,       # source
    "開催": -1.4,      # holding an event
    "関連": -1.2,      # related
    "会社": -0.75,     # company
    "会員": -0.5,      # member
}
MOTION = {
    "go", "come", "move", "roll", "pass", "hand", "bring", "run",
    "carry", "rotate", "wind", "back",
}


@lru_cache(maxsize=4096)
def roots(word):
    return set(wordnet.base_forms(word)) | {word}


@lru_cache(maxsize=4096)
def compound_value(pair):
    if pair in WORDS:
        return WORDS[pair]
    left, right = pair
    if left == "全":
        if right in "裸军軍党店":  # whole body, army, party, store
            return -2.2
        if right == "員":       # all members
            return -1.3
    if left in "升降" and right in "级級":  # upgrading/downgrading
        return -1.7
    if left in "转轉" and right == "型":   # transformation
        return -1.4
    if left in "運运旋翻" and right in "转轉":  # rotation
        return 4.0 if left == "翻" else 2.5
    if right == "界" and left in "限臨临":  # limits/critical boundaries
        return 1.7 if left == "限" else 3.0
    if left == "回" and right in "归歸":    # returning
        return 3.0
    if right == "贫" and regex.fullmatch(r"\p{Script=Han}", left):
        return -1.0
    if right not in "会會店師师連连":
        return 0.0
    gloss = " ".join(cedict.glosses(pair) + jmdict.glosses(pair)).lower()
    if right in "連连" and gloss:
        return -0.8
    if right == "店" and any(w in gloss for w in ("shop", "store", "booth")):
        return -1.0
    if right in "会會" and any(w in gloss for w in (
        "meeting", "association", "join", "conference", "convention",
        "assembly", "fair", "society", "member", "club",
    )):
        return -1.0
    if right in "師师" and any(w in gloss for w in (
        "teacher", "nurse", "lawyer", "instructor", "lecturer",
    )):
        return -0.75
    return 0.0


def opening(token):
    if token.startswith("//"):
        return 3.45 if "\n" in token else 0.84
    if token.startswith(("#", "/*")):
        return 0.6
    if token.startswith(("'''", '"""')):
        return 1.3
    if token.startswith("<|"):
        return -0.45
    if token.lower() in {"he", "she", "they", "you"}:
        return -0.85
    if token.isascii() and token.isalpha():
        if token.isupper() and len(token) <= 2:
            return -0.45
        return -0.25 if len(token) <= 6 else -0.05
    return 0.0


def english(word, prev, title, leading_space):
    if word in {"about", "around", "round", "-around", "-round"}:
        if prev == "all":
            if word == "about":
                return 5.0 if title else 3.3
            return 4.5
        if word in {"around", "-around"} and "wrap" in roots(prev):
            return 3.9 if prev == "wrap" else 1.6
        if prev == "yarn" and word == "around":
            return 2.1
        if prev == "year" and word in {"round", "-round"}:
            return 4.5
        if prev == "round" and word == "about":
            return 5.5
        if "turn" in roots(prev):
            return 1.45 if word == "around" else 0.6
        if roots(prev) & MOTION:
            return 0.65
        return {"about": -0.14, "round": -0.23}.get(word, -0.03)
    if word in {"contact", "-contact"}:
        if prev in {"non", "inter"}:
            return 1.5
        if prev == "full":
            return 3.0
        return 1.0 if prev in {"in", "into", "close"} else -0.12
    if prev == "un" and not leading_space:
        return {"clean": 2.2, "ready": 2.0, "bounded": 0.9}.get(word, 0.0)
    if word == "table":
        if prev == "round":
            return 4.0
        if prev == "around":
            return 1.8
        if prev == "on" and not leading_space:
            return 2.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    tail = b"" if start else carry[1]
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    joined = tail + raw
    state = (doc, joined[-80:])
    if token == "··":
        return state, 1.03
    if start:
        return state, opening(token)
    pair = joined.decode("utf-8", "replace")[-2:]
    if len(pair) == 2 and len(raw) < len(pair.encode()):
        value = compound_value(pair)
        if value:
            return state, value
    match = re.search(r"([A-Za-z]+)[^A-Za-z]*$", tail.decode("utf-8", "replace"))
    prev = match[1].lower() if match else ""
    value = english(token.strip().lower(), prev, token.strip().istitle(),
                    token.startswith(" "))
    return state, value

programs.haiku:
"""Layer-1 MLP neuron 1345 (the component's activation), as a short rule set.

The component is essentially one neuron of layer 1's MLP, and its sign and size depend on
the exact word. Only the clear patterns are written here.

  * 'about' / 'around' / 'round' used in the sense of going all the way round, after a word
    that sets it up: "all about", "all around", "year-round", "wrap around" give about +4.5;
    "turned about", "yarn around", "wrapped around", "turns around" give about +1.5.
  * a run of middle dots ('··') fires weakly (+1).
  * the first token of a document has no earlier context, so its value is set by the token
    alone: a word with no leading space is negative (-0.25), a special token such as
    <|im_start|> is negative (-0.45), everything else is about 0.
"""

READS = ()

PHRASE_END = {"about", "around", "round"}
STRONG = {"all", "year", "round", "wrap"}
WEAK = {"turn", "turns", "turned", "turning", "yarn", "wraps", "wrapped", "wrapping",
        "roll", "rolls", "back"}
DOT_RUN = "··"


def _word(s):
    return s.strip().lstrip("-").lower()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    cur = tokens[-1]
    first = len(tokens) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if first:
        if cur.startswith("<|"):
            return None, -0.45
        if cur[:1].isascii() and cur[:1].isalpha() and not cur.startswith(" "):
            return None, -0.25
        return None, 0.0
    if len(tokens) > 1 and _word(cur) in PHRASE_END:
        before = _word(tokens[-2])
        if before in STRONG:
            return None, 4.5
        if before in WEAK:
            return None, 1.5
    if cur == DOT_RUN:
        return None, 1.0
    return None, 0.0

programs.sol:
"""Sparse word-ending responses in Japanese and Chinese, not a semantic classifier.

Recognize byte-split thread-working characters and selected compound endings.
The largest negative responses are news-reporting compounds, network/technical
paths, and 繰り (repeating).
文 in report/reply compounds is positive, as are paired middle dots and an
initial space-plus-period. Unrecognized text stays near zero.
"""
import regex
import cedict

READS = ()


def response(previous, raw, first):
    text = raw.decode('utf-8', 'replace')
    last = previous.decode('utf-8', 'replace')[-1:]
    if text == '··':
        return 1.17
    if first and text == ' .':
        return 2.32
    if raw and 128 <= raw[0] < 192:
        char = (previous + raw).decode('utf-8', 'replace')[-1:]
        if char in '締繰':  # Tightening and winding thread.
            return -2.8
        if char in '綺織':  # Patterned silk and weaving.
            return -1.4
        if char == '拠':
            return -1.25
        if char == '摂':
            return -0.95
    if text == 'り':  # Japanese continuative / nominalized verb endings.
        if last == '繰':
            return -3.8
        if last and last in '盛磨掘搾榨':  # Piling, polishing, digging, squeezing.
            return -1.65
        if regex.fullmatch(r'\p{Script=Han}', last):
            return -0.15
    if last in ('网', '網') and text.startswith('路'):
        return -3.1
    if text in ('路', '道'):
        gloss = ' '.join(cedict.glosses(last + text)).lower()
        if regex.search(
                r'\b(channel|circuit|network|duct|drain|data link)s?\b', gloss):
            return -1.2
    if (text == '品' and previous.decode('utf-8', 'replace')
            .endswith(('纺织', '紡織'))):
        return -3.0
    if (last, text) == ('报', '导'):
        return -3.9
    if (last, text) == ('報', '道'):
        return -3.0
    if text == '文':
        if last in ('报', '報'):
            return 1.08
        if last == '回':
            return 2.7
    if (last, text) == ('映', '画'):
        return -1.8
    if (last, text) == ('写', '真'):
        return -0.72
    if (last, text) == ('製', '品'):
        return -1.15
    if regex.fullmatch(r'\p{Script=Han}', last):
        if text == '器':  # Instrument/device suffix.
            return -0.18
        if regex.fullmatch(r'\p{Script=Han}', text):
            return -0.004
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = b'' if first else carry[1]
    raw = prefix.token_bytes[-1]
    value = response(previous, raw, first)
    return (doc, (previous + raw)[-12:]), value

"""A lexical/spelling detector, not a single semantic topic.

The main negative responses are to sex-, session/sess-, possession-, and
season words. Splitting 'ses' or 'sex' across tokens often strengthens the
response. Some corresponding Cyrillic and Japanese spellings, Chinese
会话/會話 ('conversation/session'), and the season character 季 are included.
A few smaller rules cover 'of' after these nouns, S3, and positive 'seki'.
Numbers approximate training averages; unrecognized text stays near zero.
Only the preceding token is remembered, separately within each document.
"""
import re

READS = ()

SEASON_MODIFIERS = {
    'regular', 'hurricane', 'rainy', 'dry', 'wet', 'growing',
    'baseball', 'football', 'basketball', 'soccer', 'hockey',
}


def response(text, previous):
    t = text.lower().lstrip(' \t\n.,:;_-/([\"\'')
    p = previous.lower()
    if t.startswith(('sexuality', 'sexually')):
        return -1.1
    if t.startswith('sexy'):
        return -0.8
    if t.startswith(('sexual', 'sexo', 'sexe')):
        return -3.2
    if t.startswith('sexp'):
        return -1.4
    if t.startswith(('sex', 'seks', 'секс', 'セックス')):
        return -5.0
    if t.startswith('sessions'):
        return -3.8
    if t.startswith(('session', 'sess', 'сесс', 'セッション')):
        return -5.8
    if 'Session' in text:
        return -5.7  # e.g. a session accessor or type name in code
    if t.startswith('possession'):
        return -3.3
    if t.startswith('possess'):
        return -1.4
    if t.startswith('seasons'):
        return -1.0
    if t.startswith('season'):
        return -4.7 if p.strip() in SEASON_MODIFIERS else -2.2
    if t.startswith(('saison', 'сезон', 'sesión')):
        return -3.2
    if t.startswith('sesame'):
        return -2.3
    if t in ('ses', 'sesqu'):
        if text.islower() and not text[0].isspace():
            return -3.9
        return -1.7 if text.strip().islower() else -3.0

    # Completions of spellings begun in the previous token.
    if t == '3' and p.strip(' _') == 's':
        return -1.8
    if t.startswith('ッション') and p.endswith('セ'):
        return -8.3
    if t.startswith('ame') and p.endswith(('ses', 'es')):
        return -5.4
    if p.endswith('se') and t.startswith('ki'):
        return 3.0
    if text and text[0].isalpha():
        fragment = re.search(r'[^\W\d_]+$', p)
        fragment = fragment.group() if fragment else ''
        if p.endswith('s') and t.startswith(('es', 'ex', 'ez')):
            if text[0].isupper() and previous[-1].islower():
                return -0.001  # a camel-case word boundary
            if fragment == 's':
                return -8.3
            if re.search(r'(possess|obsess|session)', p + t):
                return -6.9
            return -0.6
        if p.endswith('с') and t.startswith(
            ('екс', 'есс', 'ез', 'ещ', 'ес')
        ):
            return -5.2
        if fragment in ('se', 'sé'):
            if t.startswith('x'):
                return -8.1
            if t.startswith('s'):
                return -3.6
            return -0.35
        if fragment == 's' and t.startswith('e'):
            return -0.3
        if p.endswith('с') and t.startswith('е'):
            return -0.35
        if (re.search(r'(saison|sæson)', p + t)
                and not re.search(r'(saison|sæson)', p)):
            return -4.3
    if p.endswith('sec') and t.startswith('ession'):
        return -6.3
    if t == 'of' and p.strip() in {
        'possession', 'seizure', 'seat', 'season', 'session', 'sessions',
    }:
        return -1.9
    if p.endswith(('会', '會')) and t.startswith(('话', '話')):
        return -9.0
    if t.startswith('季'):
        return -0.85
    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    return (doc, text), response(text, previous)

"""A sparse detector of code syntax and structured-output boundaries.

Statement-leading ``if`` is positive, with a smaller response in Python.
Selected JSON/tool-call and import-string boundaries are negative. Imports,
Rust attributes, diff headers and test/timing output have separate rules;
NUL bytes get a small negative value. These are recurring training patterns,
not a complete account of the component. Other text stays near zero. A short
causal text tail, cleared at document boundaries, supplies context.
"""
import re

READS = ()


def source_text(text):
    # JSON-embedded code may have several escape backslashes.
    return re.sub(r'\\+[nt]',
                  lambda m: '\n' if m[0][-1] == 'n' else '\t', text)


def predict(token, before):
    word = token.strip()
    if word in ('if', 'IF'):
        text = source_text(before)
        line = text.rsplit('\n', 1)[-1]
        boundary = (re.fullmatch(r'\s*[+-]?\s*(?:\d+\s*)?', line) or
                    re.search(r'(?:[;{}]|\belse)\s*$', line))
        python = bool(re.search(r'\bdef |\bself\.|```python', text))
        if not python:
            python = text.count(':\n') > text.count(';') + text.count('{')
        if boundary or token == '\tif':
            return 0.32 if python else (0.62 if token != ' if' else 0.80)
        return 0.001

    # Whitespace distinguishes nested inline objects from record openings.
    if token == '{"':
        if '<tool_call>' in before[-40:]:
            direct = re.search(r'assistant\n<tool_call>\n$', before)
            return -1.6 if direct else -2.1
        if not before.rsplit('\n', 1)[-1].strip():
            return -2.35
        return -0.15
    if word in (',"', ':"', '":"', '","', '":{"'):
        return -0.45 if ':' in word else -0.25
    if word == '":':
        if re.search(r'<tool_call>\s*\{"[^"]+$', before[-120:]):
            return -0.30
        return -0.09
    if word.endswith('"') and word[:-1] and not word[:-1].strip('\\'):
        text = source_text(before)
        if re.search(r'\bimport\s*(?:\([^)]*)?$', text):
            return -1.3
        if before and not text.rsplit('\n', 1)[-1].strip():
            return -0.9
        return -0.33

    # Only a quote which opens a field/import, not a closing quote, is strong.
    if token in ('"', ' "') or (word.startswith('"') and '\n' not in token):
        text = source_text(before)
        line = text.rsplit('\n', 1)[-1]
        if re.search(r'\bimport\s*(?:\([^)]*)?$', text):
            return -2.5
        if re.search(r'#\s*include\s*$', line):
            return -1.0
        if before and re.fullmatch(r'\s*(?:\d+\s+)?', line):
            if re.search(r'[\[{][^\]}]*$', text):
                return -0.6
        if token == ' "' and before.rstrip().endswith(':'):
            return 0.10
        if token == ' "' and before.rstrip().endswith(','):
            in_tool = before.rfind('<tool_call>') > before.rfind('</tool_call>')
            return -0.28 if in_tool else -0.07

    if word in ('java', 'static', '(') and re.search(r'\bimport\s*$', before):
        if word == 'java':
            return 1.35
        if word == 'static':
            return 8.1
        if token.endswith('\n') and word == '(':
            return -2.1
    if word == 'void' and re.search(r'\bstatic\s*$', before):
        return 1.15
    if word == 'declare' and '<?php' in before[-250:]:
        return -3.2
    if word in ('allow', 'warn', 'deny', 'forbid', 'cfg', 'derive'):
        if before.endswith('#[') or before.endswith('#!['):
            if word == 'derive':
                return -1.4
            return -3.6 if word == 'allow' else -2.0
    if word == 'git' and before.endswith('diff --'):
        return -2.2
    if token == ' b' and before.endswith('+++'):
        return -3.0

    if token == '\x00':
        return -0.16
    if token == ' ms' and re.search(r'\d\s*$', before):
        return -0.92
    if token == ' passed' and re.search(r'\d\s*$', before):
        line = before.rsplit('\n', 1)[-1]
        return -1.3 if '=' in line or 'Test Suites:' in line else -0.35
    if token == ' PASS' and re.search(r'---\s*$', before):
        return -0.40
    return 0.001


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    value = predict(token, before)
    return (document, (before + token)[-2048:]), value

programs.haiku:
"""Layer-1 MLP down_proj component 1350.

A mostly quiet feature with a clear sign split. It is negative on the opening of JSON objects
(`{"` at the start of a line, e.g. tool-call arguments) and on quoting of serialized data
(line-leading quotes, escaped quotes), and on web-page counters ("views", "likes", "replies").
It is positive on code: an `if` that opens a line of code, and Java/C library names
(`import java...`, `#include <stdlib.h>`)."""

READS = ()

CODE_WORDS = {"java": 1.1, "stdlib": 1.5, "stdio": 1.5, "iostream": 1.0,
              "namespace": 0.3, "package": 0.15, "def": 0.15, "static": 0.15}
COUNTER_WORDS = {"views": -0.6, "likes": -1.1, "replies": -1.2, "reply": -0.6}


def line_start(prefix):
    """True if the newest token opens a line (only indentation before it), or starts a document."""
    t = len(prefix) - 1
    docs, strs = prefix.document_ids, prefix.token_strings
    i = t - 1
    while i >= 0 and docs[i] == docs[t] and strs[i].strip() == "" and "\n" not in strs[i]:
        i -= 1
    return i < 0 or docs[i] != docs[t] or "\n" in strs[i]


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    s = tok.strip()
    value = 0.0
    if tok.startswith('{"') and line_start(prefix):
        value = -1.8
    elif s == '"' and line_start(prefix):
        value = -0.3
    elif "\\\"" in tok:
        value = -0.25
    elif s == "if" and line_start(prefix):
        value = 0.7
    elif s in CODE_WORDS:
        value = CODE_WORDS[s]
    elif s in COUNTER_WORDS:
        value = COUNTER_WORDS[s]
    elif s == "-doc":
        value = -3.5
    return carry, float(value)

programs.sol:
"""Approximate manner comparisons and textual cross-references.

Boost 'as described/shown/before', equivalence ('the same ... as'), copulas,
and exceptions. Suppress 'as' after 'such', 'well', or 'known'. Reference words
have weaker responses outside these constructions. Most other tokens return zero.
The verb table's columns are a baseline and four explicit context bonuses.
Keep twelve recent token words; clear them at document and sentence boundaries.
"""
READS = ()

DESCRIPTION = {'described'}
DEMONSTRATION = {'shown', 'indicated', 'discussed', 'outlined'}
REFERENCE = {
    'defined', 'specified', 'determined', 'mentioned', 'stated', 'provided',
    'listed', 'explained', 'reported', 'illustrated', 'noted', 'argued',
    'computed', 'calculated', 'recommended', 'instructed', 'requested',
}
CONDITION = {
    'required', 'needed', 'expected', 'desired', 'appropriate', 'necessary',
    'promised',
}
APPLICATION = {'used', 'applied', 'suggested', 'done'}
REFERENCES = DESCRIPTION | DEMONSTRATION | REFERENCE
PROCEDURES = {
    'procedure', 'method', 'technique', 'step', 'process', 'equation',
    'embodiment', 'protocol', 'instruction', 'result', 'property', 'manner',
}
PROCEDURES |= {w + 's' for w in PROCEDURES} | {'properties', 'processes'}
EQUIVALENT = {'same', 'similar', 'identical'}
# baseline, after 'as', after 'previously', passive/attributive, recent 'as'
VERBS = (
    (DESCRIPTION, (1.1, 5.7, 3.7, 0.7, 1.2)),
    (DEMONSTRATION, (0.7, 3.2, 0.6, 0.7, 0.0)),
    (REFERENCE, (0.2, 2.6, 0.6, 0.3, 0.3)),
    (CONDITION, (0.1, 2.1, 0, 0.0, 0.1)),
    (APPLICATION, (0.0, 1.9, 0.0, 0.0, 0.1)),
)


def response(word, h):
    prev = h[-1] if h else ''
    prev2 = h[-2] if len(h) > 1 else ''
    if word == 'as':
        value = 0.3
        if prev in {'such', 'well', 'long', 'far', 'soon', 'known', ',', '.'}:
            value += -0.3
        elif prev in {'are', 'were'}:
            value += 3.4
        elif prev in {'is', 'was'}:
            value += 2.3
        elif prev in {'be', 'been', 'being', 'am'}:
            value += 0.9
        elif prev == 'except':
            value += 5.9
        elif prev in {'exactly', 'precisely'}:
            value += 3.8
        elif prev.endswith(('exception', 'error')) and 'except' in h[-4:]:
            value += 2.0
        elif prev in EQUIVALENT:
            value += 0.0
        elif prev in REFERENCES or prev == 'given':
            value += 0.9
        elif prev.endswith('ed'):
            value += 0.2
        elif prev in {'thus', 'proceed', 'proceeding', 'essentially'}:
            value += 2.6
        elif prev == 'set':
            value += 1.5
        if prev in PROCEDURES:
            value += 1.3
        if EQUIVALENT.intersection(h[-12:]):
            value += 2.1
        return value
    for words, (base, after_as, earlier, passive, recent) in VERBS:
        if word in words:
            value = base
            if prev == 'as':
                value += after_as
            elif prev == 'previously' or (
                prev2 == 'as' and prev in {'already', 'briefly', 'expressly'}
            ):
                value += earlier
            if prev in {'are', 'were', 'been', 'the'}:
                value += passive
            if prev in PROCEDURES:
                value += 0.6
            if 'as' in h[-3:] and prev != 'as':
                value += recent
            if 'unless' in h[-2:]:
                value += 1.2
            return value
    if word in {'above', 'below', 'earlier', 'before', 'previously'}:
        value = 0.1
        if word == 'previously':
            value += 1.4
        if prev in {'as', 'like'}:
            value += 3.9
        elif prev in REFERENCES:
            value += 0.9
            if prev2 == 'as':
                value += 0.7
            if word == 'previously' or prev == 'described':
                value += 1.9
        elif prev in {'see', 'steps', 'detail', 'details'}:
            value += 1.6
        return value
    if word == 'follows':
        return 0.2 + (2.3 if prev == 'as' else 0)
    if word == 'otherwise':
        exception = prev in REFERENCES or 'unless' in h[-6:]
        return 0.6 + (3.7 if exception else 0)
    if word == 'according':
        intro = not prev or prev in {',', '.', 'but', 'and'}
        return 0.9 + (-0.9 if intro else 0)
    if prev == 'as' and word in {'in', 'per', 'such'}:
        return {'in': 1.8, 'per': 2.3, 'such': 1.4}[word]
    if word == 'in' and prev in REFERENCES and prev2 == 'as':
        return 0.4
    if word == 'so' and prev == 'like':
        return 4.4
    if word in {'usual', 'normal'}:
        comparison = prev in {'as', 'than', 'to', 'from', 'with'}
        return 0.2 + (0.6 if comparison else 0)
    if word in {'usually', 'typically', 'commonly'}:
        return -0.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    h = carry[1] if carry is not None and carry[0] == doc else ()
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    boundary = raw[:1].isspace() or not h or carry[2]
    value = response(word, h) if boundary else 0.0
    # These connectives mean 'as' / 'as follows' in Arabic and Chinese.
    if word in {'كما', '如下'}:
        value = 2.6
    if word in {'<|endoftext|>', '<|im_start|>', '.', '?', '!'}:
        h = ()
    else:
        h = (h + (word,))[-12:]
    separated = bool(raw) and not raw[-1].isalnum()
    return (doc, h, separated), float(value)

programs.haiku:
"""Cross-reference and manner phrases in technical and academic prose.

Component layers.1.mlp.down_proj:1351 is strongest on the word that completes a stock
"as X" phrase, where X points back or forward to something stated elsewhere, or to a manner:
"as described", "as shown", "as previously stated", "as above", "as follows", "as needed",
"as per", "as in", "like so", "like this". It is weaker on some of these words without "as"
("was described", "previously", "otherwise", "according to", "above"). The token " as" itself
is mildly active, and more so in equative or definitional uses ("is as", "the same as",
"defined as"). It is near zero in fixed frames ("such as", "as well as", "known as").

Rule, per token (words lowercased and stripped; the context resets at each document):
  * STRONG reference word right after "as", "like" or "per": 5. Elsewhere: 1.
  * MILD reference word right after "as", "like" or "per": 2.5. Elsewhere: 0.15.
  * "in", "so", "this", "that", "such", "same", ... right after "as" or "like": 2.
  * the token " as" (leading space), lowercase: 2.5 after same/is/are/was/be/were/exactly/not;
    1.2 after defined/recorded/error/computed/calculated/given; 0 after such/well/known/long/
    far/to/,/and/but; else 0.45.
  * everything else, including the generic word after "as" ("as a", "as the"): 0.
"""

READS = ()

# Words that point back to, or forward to, something stated elsewhere, or a manner.
STRONG = {"described", "shown", "previously", "otherwise"}
MILD = {
    "according", "above", "below", "discussed", "indicated", "provided", "determined",
    "specified", "listed", "mentioned", "forth", "defined", "expected", "required", "stated",
    "needed", "given", "follows", "following", "before", "thus", "demonstrated", "computed",
    "applied", "noted", "appropriate", "per",
}
# Words that count only right after an opener ("as in", "as such", "like this").
AFTER_OPENER = {"in", "so", "this", "that", "such", "steps", "manufacturer", "same", "set",
                "prompts", "follow", "like"}
OPENERS = {"as", "like", "per"}
# The word before " as": equative ("is as", "the same as"), definitional ("defined as"), fixed.
COPULA_BEFORE_AS = {"same", "is", "are", "was", "be", "were", "exactly", "not"}
DEFINED_BEFORE_AS = {"defined", "recorded", "error", "computed", "calculated", "given"}
FIXED_BEFORE_AS = {"such", "well", "known", "long", "far", "to", ",", "and", "but"}


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    words = prefix.token_strings
    cur = _word(words[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(words[-2]) if same_doc else ""
    after_opener = prev in OPENERS

    if cur in STRONG:
        value = 5.0 if after_opener else 1.0
    elif cur in MILD:
        value = 2.5 if after_opener else 0.15
    elif cur in AFTER_OPENER and after_opener:
        value = 2.0
    elif words[-1] == " as":
        if prev in COPULA_BEFORE_AS:
            value = 2.5
        elif prev in DEFINED_BEFORE_AS:
            value = 1.2
        elif prev in FIXED_BEFORE_AS:
            value = 0.0
        else:
            value = 0.45
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Local template completions, mostly source-code and repository boilerplate.

Predict a typical activation when a token completes one of the listed idioms.
Shebangs and strict-mode directives get larger values at document beginnings.
Keep only the current document's last 160 characters; predict zero elsewhere.
This approximates specific templates, not a general programming-topic detector.
"""
import re

READS = ()


def predict(before, token):
    # File prologues and Python special names.
    if token == '/env' and before.endswith('/usr/bin'):
        if before.endswith('#!/usr/bin'):
            start = before[:-len('#!/usr/bin')]
            return 27.6 if not start or start.endswith('<|endoftext|>') else 18.7
        if before.endswith(('#! /usr/bin', '# !/usr/bin')):
            return 8.0 if before.endswith('#! /usr/bin') else 19.4
    if token == ' strict' and before.endswith(('"use', "'use")):
        start = before[:-4]
        return 14.8 if not start or start.endswith('<|endoftext|>') else 4.0
    if before.endswith('__'):
        names = {
            'future': 10.2,
            'author': 8.0,
            'str': 2.3,
            'name': 1.7,
            'main': 1.8,
        }
        if token in names:
            return names[token]
    if token == '_function' and before.endswith('print'):
        return 17.8 if '__future__' in before else 0.0

    # Standard license endings, ignoring whitespace and comment decoration.
    if token in (' License', ' LICENSE', ' SOFTWARE', ' DAMAGE', ' Apache'):
        clean = before.replace('\\n', ' ').replace('\\t', ' ')
        words = re.findall(r'[A-Za-z]+', clean)
        if token == ' License' and words[-3:] == ['limitations', 'under', 'the']:
            commented = any(mark in before for mark in ('*', '//', '#'))
            return 15.0 if commented else 6.0
        if token == ' SOFTWARE' and words[-4:] == ['OTHER', 'DEALINGS', 'IN', 'THE']:
            return 15.3
        if token == ' DAMAGE' and words[-1:] == ['SUCH']:
            return 11.7 if before.endswith('POSSIBILITY OF SUCH') else 5.4
        if token == ' Apache' and words[-3:] == ['Licensed', 'under', 'the']:
            return 5.0
        if token == ' LICENSE' and before.endswith(('See', 'see', 'in the')):
            return 12.5 if before.endswith('See') else 6.3

    # Repository metadata and URL domains.
    if token == 'ame' and before.endswith('<repon'):
        return 30.7
    if token == 'ars' and before.endswith('<gh_st'):
        return 11.5 if '<reponame>' in before else 19.5
    if token == '.com' and before.endswith('github'):
        if before.endswith('https://github'):
            return 5.1
        if before.endswith('git://github'):
            return 4.0
        return 2.8 if before.endswith('http://github') else 1.5
    if token == '.com' and before.endswith('githubusercontent'):
        return 5.2
    if token == 'github' and before.endswith('://'):
        return 1.5
    if token == '.org' and before.endswith('travis-ci'):
        return 7.6
    if token == 'adge' and before.endswith('shields.io/b'):
        return 11.3
    if token == '_modules' and before.endswith('node'):
        return 2.3 if before.endswith('/node') else 1.7
    if token == '_components' and before.endswith('dash_html'):
        return 5.0

    # Code syntax, patches, test logs, and documentation.
    if token == ' b' and before.endswith('+++'):
        return 6.5
    if token == 'git' and before.endswith('diff --'):
        return 1.6
    if token in (' PASS', ' FAIL') and before.endswith('---'):
        return 1.1
    if token == ' grep' and before.endswith('|'):
        return 2.4
    if token in ('derive', 'error') and before.endswith('#['):
        return 6.6 if token == 'derive' else -2.5
    if token == 'inheritDoc' and before.endswith('{@'):
        return 3.2
    if token in ('returns', 'value', 'module') and before.endswith('<'):
        return 2.4
    if token == ' static' and before.endswith('import'):
        return 2.6
    if token == 'Operator' and before.endswith('\\DeclareMath'):
        return 6.8
    if token == '![' and before.endswith('['):
        return 6.1
    if token == 'NAME' and before.endswith('<'):
        return 12.0
    if token == 'EMAIL' and before.endswith(('<', '|')):
        return 6.0
    if token in (' page', ' pages') and before.endswith('This preview shows'):
        return 8.2 if token == ' pages' else 5.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-160:]), predict(before, token)

"""Estimate the sparse pulse at the start of bracketed content.

Nested delimiters, regex symbols and progress bars produce negative pulses.
A few recognizable content classes (types, lint controls, email placeholders,
edit links) produce positive pulses. Most text is zero. Fused notation and
notation split across tokens have different strengths. The only memory is the
preceding nonblank token, reset at document boundaries. Lexical quirks are
intentionally not modeled word by word.
"""

READS = ()

# Two opening marks in a single token: tuples, objects, emphasis, regex, code.
FUSED = {
    '[(': -3.1,
    '[{': -3.4,
    '[*': -2.6,
    '[^': -2.2,
    '[<': -3.5,
    '[`': -2.8,
    '{(': -3.9,
    '{|': -1.9,
    '<{': -3.4,
}
TYPES = {'void', 'string', 'object', 'array', 'list', 'dict',
         'int', 'float', 'bool', 'char'}


def pulse(token, previous, first):
    s, p = token.strip(), previous.rstrip()
    if not s:
        return 0.0
    if ('{(' in s or '[{' in s) and p in {'left', 'frac'}:
        return -1.3                 # LaTeX argument delimiters
    if '{(' in s and ')' in s:
        return -0.5                 # empty callback arguments
    if '[(' in s and p.endswith('!'):
        return -6.3                 # image/link notation
    for marks, value in FUSED.items():
        if marks in s:
            return value
    if '<(' in s and ')' not in s:
        return -1.8
    if p.endswith('['):
        if s.startswith('(') and ')' not in s:
            return -3.2 if token[0].isspace() else (-7.8 if s == '(' else -3.8)
        if s.startswith('{') and '}' not in s:
            return -1.0 if '\n' in previous else -2.6
        if s == '<':
            return -7.5
        if s.startswith('?'):
            return -5.5
        if len(s) > 3 and set(s) <= {'=', '>'} and s.count('=') > 3:
            return -8.3             # progress bar
        if s in {'*', '**'}:
            return -8.1 if s == '*' else -4.8
        if s.startswith('^'):
            return -2.7             # negated regex character class
        if s.startswith('@'):
            return -1.2             # citation
        if s.startswith(('!', '%', '+', '.', '–')):
            return -2.1
        if s.startswith(('"', "'", '\\"')):
            return -0.5
        if s.startswith('`${'):
            return -3.1             # computed property
        if not token[0].isspace():
            if p.endswith('#[') and s in {'warn', 'allow', 'deny', 'forbid'}:
                return 3.6          # lint-control attribute
            if s == 'Command':
                return -1.9         # tool completion log header
            if s == 'The':
                return -0.9         # bracketed prose annotation
            if s == 'email':
                return 5.1          # email-obfuscation placeholder
            if s in TYPES:
                return 2.5
            if s == 'edit':
                return 3.0          # wiki edit control
    if p.endswith('{'):
        if s.startswith('(') and ')' not in s:
            return -1.5 if token[0].isspace() or s != '(' else -4.2
        if s == '|' and '\n' not in previous:
            return -4.2
        if s in {'<', '**'}:
            return -2.3
        if s == '%':
            return -1.5             # template tag
    if p.endswith('|') and s.startswith('(') and ')' not in s:
        return -0.4 if token[0].isspace() else -2.6
    if p.endswith('(') and s.startswith('(') and token[0].isspace():
        return -0.6
    if first and s == '(':
        return -0.5 if token[0].isspace() else -3.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    value = pulse(token, previous, first)
    return (doc, token if token.strip() else previous), value

programs.haiku:
"""Layer 1, MLP down-projection, component 1353: an opening-bracket detector.

The component is quiet on almost all text. It goes strongly negative just after an
opening square bracket "[" (or a brace "{" in LaTeX-style "^{(" and "}{("):
  * a symbol such as ? ( < * = ! + ^ { right after "[", as in "Kudos [?]",
    "print("[*] ...", "Building [=====>";
  * "(" right after a token that ends in "{", as in "x^{(" or "}{(";
  * a token that starts with "[" and another symbol, such as "[(", " [{", " [*", " [<";
  * "Command" right after "[" (the "[Command finished ...]" banner).
Everywhere else the prediction is 0.
"""

READS = ()

SYMBOLS_AFTER_BRACKET = set("?<(*=!+^{")
SYMBOLS_STACKED = set("({*<`")


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip()
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip() if same_doc else ""
    if prev.endswith("[") and any(ch in SYMBOLS_AFTER_BRACKET for ch in cur):
        return carry, -4.0
    if prev.endswith("{") and cur == "(":
        return carry, -4.0
    if prev == "[" and cur == "Command":
        return carry, -1.9
    if len(cur) >= 2 and cur[0] == "[" and cur[1] in SYMBOLS_STACKED:
        return carry, -3.3
    return carry, 0.0

