"""Approximate a negative signal for anonymous functions and parameter openings.

The large responses mark function expressions, async functions, arrow-parameter
parentheses, and Ruby/Rust closure bars. Smaller responses mark catch clauses,
Python's first `self` parameter, and CommonJS imports. Named declarations and
ordinary prose normally get zero. A short suffix and a one-token signature state
provide context; both reset at document boundaries. This is a syntax heuristic,
not a complete parser, and does not model the component's small lexical effects.
"""
import re

READS = ()

# Familiar function-taking methods and global callback APIs.
CALLBACK = (
    r'(?:\.(?:map|flatMap|flat_map|filter|forEach|for_each|reduce|find|'
    r'some|every|then|catch|finally|sort|sort_by_key|and_then|'
    r'unwrap_or_else|on|once|addEventListener|setOn\w*Listener|'
    r'execute|register|use|eventHandler|reply)|'
    r'\b(?:it|test|describe|suite|setup|beforeEach|afterEach|beforeAll|'
    r'afterAll|useEffect|useCallback|setTimeout|setInterval|readdir|rename))'
)
ERROR_NAMES = {'e', 'err', 'error', 'event'}


def syntax_value(token, before, stage):
    s = token.strip()
    b = before.replace('\\n', '\n').replace('\\t', '\t').rstrip()
    b = re.sub(r'\n *\d+\t[ \t]*$', '', b).rstrip()
    expression = bool(re.search(r'[=(,:\[]$|\b(return|yield|default)$', b))
    callback = bool(re.search(CALLBACK + r'\s*\([^;\n]*$', b))
    direct = bool(re.search(CALLBACK + r'$', b))
    m = re.fullmatch(r'([=(,:]?)(function|async|func|lambda)', s)
    if m:
        fused, word = m.groups()
        if word in ('function', 'async'):
            python_variable = re.search(r'function\.(arguments|name)|\bdef\b', b)
            bare_on_new_line = (
                not token.startswith(' ')
                and before.endswith(('\n', '\\n'))
            )
            if (python_variable or bare_on_new_line
                    or (word == 'async' and not fused
                        and not token.startswith(' '))):
                return 0.0, ''
            if fused or expression or stage == 'async':
                value = -8.4 if fused else -10.4
                if fused == '(' and word == 'function':
                    value = -10.5 if re.search(r'[\w)\]]$', b) else -5.0
                if word == 'async':
                    value = (-4.0 if direct else 0.0) if fused else -9.3
                return value, word
        elif word == 'lambda' and (fused or expression):
            return (-5.5 if not fused and b.endswith('=') else -3.8), ''
        elif word == 'func' and not re.search(r'\.py[\s\S]*\bline\b', b):
            if fused:
                if re.search(r'\binspect\.', b):
                    return 0.0, ''
                go_context = re.search(r'\bfunc\b|\bdefer\b|Func$', b)
                return (-8.5 if go_context else -3.5), 'func'
            if token.startswith(' '):
                if re.search(r'\b(go|defer)$|[=,:]$', b):
                    return -9.0, 'func'
                if re.search(r'\breturn$', b):
                    return -8.0, 'func'
                if expression:
                    return -8.0, 'func'
                if re.search(r'\bfunc\s+\w+[^{}\n]*$', b):
                    return -4.4, 'func'
    elif s == 'require' and b.endswith('='):
        return -3.0, ''
    elif s in ('|', '(|', '{|'):
        if s == '(|' and re.search(r'\.[\w]+$|\bfn\b|\blet\b', b):
            return -7.5, 'parameter'
        if s == '{|' and re.search(r'\.[\w]+$', b):
            return -2.0, 'parameter'
        if re.search(r'\bdo$', b):
            return -8.0, 'parameter'
        if (re.search(r'\bmove$', b) and token.startswith(' ')
                and '\n' not in token):
            return -5.5, 'parameter'
        if re.search(r'!\([^()]*:$', b):
            return -4.3, 'parameter'
    elif '(' in s:
        if stage in ('function', 'async', 'func') and s.startswith('('):
            if '{' not in s:
                value = -1.4 if stage == 'func' else -3.0
                if s == '()':
                    value = -7.0 if stage == 'async' else -4.2
                elif token.startswith(' (') and stage != 'func':
                    value = -7.5
                return value, 'parameter' if s == '(' else ''
        elif s.startswith('(self'):
            return (-1.13 if re.search(r'\bdef\b[^\n]*$', b) else 0.0), ''
        elif s == '(()':
            return -4.6, ''
        elif s.startswith('((') and not s.startswith(('((\"', "(('", '(())')):
            value = -5.2 if s.startswith('(([') else -8.3
            pending = 'parameter' if direct and s == '((' else ''
            return (value if direct else -0.15), pending
        elif s in ('={(', '={()'):
            return -5.2, 'parameter' if s.endswith('(') else ''
        elif s.startswith('](') and re.search(r'\[[&=][\w, &]*$', b):
            return -5.7, ''
        elif (s.startswith('>(')
              and re.search(r'\bfunction\b|\bconst\b|\bnew Promise\b', b)):
            return -2.3, 'parameter' if s.endswith('((') else ''
        elif token.startswith(' ('):
            pending = 'parameter' if s == '(' else ''
            if re.search(r'\bcatch$', b):
                return -3.75, 'caught' if s == '(' else ''
            if re.search(r'\bswitch$|\bfunc$', b):
                return -2.2, ''
            if s == '()':
                return (-5.6 if expression or callback else 0.0), ''
            if s in ('(', '({', '([', '(\\') or s.startswith('(\n'):
                if re.search(r'\bmodule\.exports(?:\.\w+)*\s*=$', b):
                    return -10.0, pending
                if (re.search(r'\b(const|let|var)\s+\w+(?:\s*:[^;{}\n]+)?\s*=$', b)
                        and not re.search(r'\bfn\b|assert_eq!', b)):
