                    return (-2.7 if multiline else -7.0), pending
                if re.search(r'\bexport default$', b):
                    return -5.8, pending
                if callback and b.endswith((',', '(')):
                    return -5.8, pending
                if (re.search(r'\b\w+\s*:\s*$', b)
                        and re.search(r'\b(const|let|var|function|export)\b|=>', b)):
                    return -1.25, pending
    elif stage in ('parameter', 'caught') and re.match(r'\w', s):
        if s in ERROR_NAMES:
            return (-3.2 if stage == 'caught' else -4.0), ''
        return -1.2, ''
    elif (s == 'self' and b.endswith('(')
          and re.search(r'\bdef\b[^\n]*$', b)):
        return -0.95, ''
    return 0.0, ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, stage = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    s = token.strip()
    relevant = (stage or '(' in s or s in ERROR_NAMES or s in {
        'function', 'async', 'func', 'lambda', 'require', 'self', '|', '{|',
        '=function', ':function', '=lambda', '=func', ':func',
    })
    value, next_stage = (
        syntax_value(token, tail, stage) if relevant else (0.0, '')
    )
    return (doc, (tail + token)[-256:], next_stage), value

"""A detector for code conditions and diagnostic strings, not prose 'if'.

It recognizes statement starts, boolean operators inside conditions, output
and logging calls, and shell here-documents. A short text tail supplies the
syntax context; it is cleared at a new document. A second zero in prefixes
like `[00`, `-00`, and `_00` has a separate negative response. Response
sizes are calibrated on training examples. Smaller token-specific background variation is omitted.
"""
import re

READS = ()

_OUTPUT_NAME = (
    r'(?:print(?:ln)?|[vksd]?printf|fprintf|sprintf|perror|echo|input|'
    r'log(?:f|ln|error|warning)?|debugf?|infof?|warn(?:ing)?f?|'
    r'errorf?|fatalf?|tracef?|panicf?|write(?:line)?|_?dlog)'
