_OUTPUT_CALL = re.compile(
    r'\b(?:' + _OUTPUT_NAME + r'|log\.[vdiew])\s*!?\s*\(\s*'
    r'(?:(?:stderr|stdout|sys\.stderr)\s*,\s*)?'
    r'(?:\d+\t\s*)?[+]?\s*[frbu]*$', re.I
