def response(tail, s):
    w = s.strip()
    if s == '0' and re.search(r'(?:\[|[-_])0$', tail):
        return -0.46  # zero padded reference
    left = tail + s[:len(s) - len(s.lstrip())]
    line = left.rsplit('\n', 1)[-1]
    if w in ('if', 'elif', 'elseif', 'while', 'switch'):
        boundary = (s[:1].isspace() or not tail or
                    not (tail[-1].isalnum() or tail[-1] == '_'))
        if boundary and tail:
            statement = bool(_LINE_START.fullmatch(line))
            after_else = bool(re.search(r'\belse\s*$', left))
            code = bool(re.search(r'[=;{}]|\w_\w|\w\(', line))
            if w == 'elseif':
                return 1.18  # else if
            if w == 'if':
