            return 0.73 if '\\' in s else 1.04
        if re.search(r'\b(?:echo|print)\s+$', tail + before_quote):
            return 1.04  # output string
        if re.search(r'(?:\b(?:cout|cerr|clog)|\bLOG\([^)]*\)).*<<\s*$', opener):
            return 0.95  # stream output string
        if re.search(r'\b\w*(?:Error|Exception)\s*\(\s*$', opener):
            return 0.68  # exception string
        if re.search(r'\br#+$', opener):
            return 1.27  # raw string
        if re.search(r'<<<?\s*$', opener):
            return 0.4  # quoted heredoc delimiter
        if (quote and not s[quote.end():].startswith((')', ',', ';', ']')) and
                re.search(r'\b' + _OUTPUT_NAME + r'\([^\n]*\+\s*$', opener)):
            return 0.59  # concatenated output string

    if w in ('EOF', 'EOT', 'END') and re.search(r'<<<?\s*[\"\']?$', tail):
        return 1.42  # heredoc delimiter
    if '\n' in s and re.search(r'<<<?\s*[\"\']?(?:EOF|EOT|END)[\"\']?$', tail):
        return 1.03  # heredoc newline
    return 0.0  # other


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = response(tail, s)
    tail = (tail + s).replace('\\n', '\n').replace('\\t', '\t')
    tail = tail.replace('\\r', '\r')[-400:]
    return (doc, tail), value

programs.haiku:
"""Layer-1 MLP unit 1355: fires on the token that opens a code branch or a printed message.

It is a code detector. It is near zero in prose and fires on:
  - `if` starting a statement in code (after indentation, `else`, `{`, `}` or `;`): strongest;
  - `if` mid-line in code (`x = a if c else b`, comprehensions), weaker;
  - `&&`, `||`, `elif` inside a condition (a line containing `if` or `while`);
  - the opening quote of a string handed to an output call (print, echo, log, cout <<, ...).
Everything else predicts 0. This is a readable approximation: the component's exact
activation also varies with many small, diffuse token effects that it leaves out.
"""

READS = ()

IF_WORDS = {" if", "\tif", "if"}
QUOTE_OPENERS = {'("', "('", '(\\"', '(f', '(`', '("%', ' "', '\\"', '<<"', '<<"\\'}
OUTPUT_CALLS = ("print", "println", "printf", "echo", "log", "error", "warn", "Warn", "Warnf",
                "Errorf", "Printf", "Println", "Fatalf", "cout", "cerr", "info", "Info", "die",
                "perror", "alert", "trace", "write", "writeln", "Sprintf")
CODE_MARKS = set("{}();=[]<>")
DOT_RUN = "··"  # a run of middle dots, which fires weakly


def _opens_output(line):
    """True if the text before this token ends in an output call, e.g. `println!(`."""
    s = line.rstrip()
    if s.endswith("(f"):  # Python f-string opener, as in print(f"
        s = s[:-2]
    s = s.rstrip("(!").rstrip()
    return s.endswith(OUTPUT_CALLS) or s.endswith("<<")


def step(carry, prefix, upstream):
    # carry: (text of the current line so far, the last 12 tokens)
    new_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_doc:
        carry = None  # first token of a row, or of a new document: forget earlier text
    line, recent = carry if carry else ("", ())
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    value = 0.0
    if tok in IF_WORDS:
        code_marks = sum(1 for s in recent for c in s if c in CODE_MARKS)
        if prev.strip() == "" or prev.endswith("\n") or prev.strip() in ("else", "{", "}", ";"):
            value = 1.2  # `if` opening a statement
        elif code_marks >= 3:
            value = 0.4  # `if` inside an expression
    elif tok in QUOTE_OPENERS:
        if _opens_output(line):
            value = 1.0
    elif tok in (" &&", " ||", " elif"):
        if "if" in line or "while" in line:
            value = 1.2
    elif tok == DOT_RUN:
        value = 0.4
    if "\n" in tok:
        line = tok.split("\n")[-1]
    else:
        line = line + tok
    recent = (recent + (tok,))[-12:]
    return (line[-200:], recent), value

programs.sol:
"""Approximate sparse local phrase and formatting responses.

'With' after working, testing or calculation has a positive response; assistance
phrases have a negative one. Numbered-label delimiters and several familiar
text-introducing formats also have negative responses. These are separate local
constructions, not a single semantic topic. Repeated introductions are damped.
Unrecognized constructions predict zero. Only a bounded text suffix is retained.
"""
import re

READS = ()

HELP = set('help helps helped helping assist assists assisted assisting'.split())
TRIAL = set(('test tests tested testing experiment experiments experimenting '
             'practice practicing practise').split())
COMPUTE = set(('compute computing computed calculate calculated calculating '
               'obtain obtained measure measured measurement measurements '
               'simulation simulations').split())
MAKE = set(('make made manufactured produce produced done perform performed '
            'conducted operate operates operation').split())
MATH = set(('probability division computation science algebra arithmetic '
            'multiplication quantitative').split())
LABEL = set(('test case example statement requirement rule part step method '
             'lecture chapter section page day goal option figure table '
             'exercise question problem proposition theorem lemma claim '
             'program episode level volume instruction definition').split())


def response(text, token):
    """Return a repetition-counter name (if needed) and an activation."""
    word = token.strip().lower()
    if word == 'with':
        if not text:
            return '', -1.2
        words = re.findall(r'[a-z]+', text[-90:].lower())
        prev = words[-1] if words else ''
        if prev in HELP:
            return '', -1.3
        if any(w in HELP for w in words[-3:]):
            return '', -0.9
        if prev in {'work', 'working'}:
            return '', 3.05
        if prev in {'works', 'worked'}:
            return '', 2.0
        if re.search(r'\bwork(?:s|ed|ing)? (?:[a-z]+ly|together|more)\s*$',
                     text, re.I):
            return '', 1.85
        for category, value in ((TRIAL, 1.3), (COMPUTE, .95),
                                (MAKE, .8), (MATH, 1.3)):
            if prev in category:
                return '', value
        return '', .06

    # Familiar quotation and interface labels.
    if token.strip() == 'Posted' and re.search(r'\bOriginally\s*$', text):
        return 'quotation', -6.1
    if token.strip() == 'Document' and re.search(r'\bView Full\s*$', text):
        return 'document_link', -12.5
    if token.strip() == 'Tags' and re.search(r'\bShow\s*$', text):
        return 'tag_control', -1.4

    if token in (':', '：', ' (', ' -', ' –', '「', '\n', '\n\n', ' of', ' /'):
        number = re.search(r'(\w+)[ \t#-]*(\d+)\s*$', text)
        label = number.group(1) if number else ''
        if re.search(r'第[\d一二三四五六七八九十百]+[章節話回]$', text):
            return '', -1.5
        if label.lower().rstrip('s') in LABEL and label != 'case':
            if token.isspace():
                return '', -.35
            if token in (':', '：'):
                return 'numbered_colon', -2.0
            return 'numbered_detail', -1.5
        if token in (':', '：'):
            if re.search(r'(?:^|<\|endoftext\|>)Title$', text):
                return '', -3.7
            if re.search(r'\blast (?:edited|updated)\s*$', text, re.I):
                return '', -2.15
            if re.search(r'\b(?:EDIT|UPDATE|TODO|FIXME|Title|Description|'
                         r'Conclusions|Update|Edited)\s*$', text):
                return '', -1.6
            if label.istitle():
                return '', -.46
            return '', -.12 if re.search(r'\d\s*$', text) else -.04

    if re.fullmatch(r' ?(?:\*\*|#{1,6})', token):
        if re.search(r'(?:^|\n|\\n)\s*(?:>\s*)?\d+\.\s*$', text):
            if '*' in token:
                return 'numbered_bold', -2.0
            return 'numbered_hash', -2.5
    if token in ('`', '``', '```'):
        if re.search(r'(?:\n|\\n){2}\s*$', text):
            return '', .75

    # LaTeX commands introducing text, formal statements, and mathematical names.
    if token == '[$' and re.search(r'\\item$', text):
        return 'latex_item', -4.3
    if re.search(r'\\begin\{(?:theorem|lemma|claim)\}\\?$', text + token):
        return '', -1.75
    if token == '{':
        match = re.search(r'\\([A-Za-z]+)$', text)
        name = match.group(1) if match else ''
        if name in {'section', 'subsection', 'subsubsection', 'caption', 'footnote'}:
            return 'latex_detail', -2.45
        if name == 'operatorname':
            return '', 2.5
        if name == 'mathbb':
            return 'latex_number_set', 1.3
        if name == 'textbf' and re.search(r'(?:^|\n)\s*\\textbf$', text):
            return '', -4.45
        if name == 'textup':
            return '', -.35
    return '', 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, counts = '', {}
    else:
        _, text, counts = carry
    token = prefix.token_strings[-1]
    kind, value = response(text, token)
    if kind:
        previous = counts.get(kind, 0)
        value /= (1 + .5 * previous) ** .5
        counts[kind] = previous + 1
    return (doc, (text + token)[-256:], counts), float(value)

"""Approximate a code-syntax signal: assignments, returns and other exits.

A line consisting of variable names (possibly with a declaration keyword)
licenses an assignment. This excludes most equations embedded in prose and
most named arguments. Returns and exits fire after indentation or statement
punctuation, including in commented-out code. Recent braces and semicolons
strengthen returns. A separate rule captures document-opening 'Title:' labels.
