import re

READS = ()
JUMPS = {'return', 'break', 'continue', 'throw', 'raise', 'yield', 'goto'}
OPERATORS = {'=', ':=', '<-', '?', ':', '||', '&&', 'default'}
NAME = r'[A-Za-z_$][A-Za-z0-9_.$]*(?:->[A-Za-z0-9_]+)*'
