    if word not in JUMPS and word not in OPERATORS and word != 'Title':
        return state, 0.0
    if not previous and token == 'Title':
        return state, 1.19
    if previous == 'Title' and token == ':':
        return state, -6.16

    context = (previous + lead).replace('\\n', '\n').replace('\\t', '\t')
    line = context.rsplit('\n', 1)[-1]
    # Remove source-listing line numbers, diff markers and comment prefixes.
    clean = re.sub(r'^\s*\d+[ \t]+', '', line)
    clean = re.sub(r'^([+-])(?=\s)', '', clean)
    clean = re.sub(r'^(\s*)`+', r'\1', clean)
    clause = re.sub(r'/\*.*?\*/', '', clean)
    clause = re.sub(r'^\s*(?://|#)\s*', '', clause).rstrip()
    tail = context[-500:]
    braces, semicolons = '{' in tail, ';' in tail
    value = 0.0

    if word in JUMPS:
        boundary = (
            not clause.strip() or clause.endswith((')', '{', '}', ';', ':', '=>'))
            or bool(re.search(r'\belse\s*$', clause))
