        if '\t' in token or boundary:
            if word == 'return':
                value = 2.0 if braces else 1.6
                if semicolons:
                    value = 2.2
                if '\t' in token:
                    value = 2.5
                if clause.endswith('=>'):
                    value = 1.5
            else:
                value = {'break': 1.35, 'continue': 1.5, 'throw': 1.6,
                         'raise': 0.85, 'yield': 0.4, 'goto': 0.3}[word]
        elif clause.endswith('`') and (braces or semicolons):
            value = 1.6 if word == 'return' else 0.8

    elif word in ('=', ':=', '<-'):
        if BINDING.fullmatch(clean):
            name = re.search(NAME + r'\s*$', clean)[0].strip()
            if word != '=':
                value = 0.95 if word == ':=' else 1.1
            elif token.startswith(' '):
                python = bool(re.search(r'\b(?:def|self|import)\b', tail))
                value = 1.0 if python else 0.7
                if len(name) == 1:
                    value *= 0.5
                if re.search(r'\bconst\b', clean):
