        value = 1.35
    elif word in ('?', ':') and '\n' not in token:
        if word == '?' and token.startswith(' ') and (braces or semicolons):
            value = 0.7
        elif word == ':' and re.search(r'\s\?\s[^;{}?:]*$', context[-200:]):
