                value = 1.7
    elif word == '||' and (braces or semicolons):
        value = 0.3
    elif word == '&&' and (braces or semicolons):
        value = 0.1
    return state, value

"""A sparse detector of code transitions and GitHub links.

Positive responses cover construction (`new`, Go slices), return statements,
Java-style import boundaries, and comments following code on the same line.
