import re

READS = ()
ARTICLES = {'a', 'an', 'the'}
PRONOUNS = {
    'you', 'he', 'she', 'it', 'we', 'they', 'me', 'him', 'her', 'us', 'them',
    'this', 'that', 'these', 'those', 'my', 'your', 'his', 'its', 'our', 'their',
    'who', 'which',
