DECLARATIONS = {'class', 'def', 'const'}
MATH_WORD = re.compile(
    r'\b(?:theorem|lemma|integers?|primes?|divisors?|'
    r'triangle|equation|function|polynomial|sequence|converges|convergence|'
    r'odd|even|inequality|independent|variables?|rational|irrational|'
    r'contradiction|proposition)$', re.I,
)
