    numeral = number is not None and 0 <= number <= 10
    gap, gap2 = age - last, age - before
    line_age = age - newline
    # Recovery from recent numeric material takes several tokens.
    reset = 0.7 if line_age < gap else 1.0
    recent = math.exp(-max(0, gap - 1) / 3.3)
    earlier = math.exp(-max(0, gap2 - 2) / 8.2)
    adaptation = max(0.0, 1.0 - reset * (0.84 * recent + 0.18 * earlier))
    value = 0.0
    if digit:
        n = int(word)
        strength = 1.17 if n == 0 else (1.73 if n == 1 else 2.06)
        if not word.isascii():
            strength *= 1.6
