        else:
            value = -strength * adaptation
            if previous and previous[-1].isascii() and previous[-1].isalpha():
                value *= 0.95 if len(previous.strip()) == 1 else 0.59
        if age == 0:
            value = 0.69
    elif numeral:
        value = -0.7 * adaptation
    elif word in NUMBER_WORDS:
        value = -0.6 * adaptation
    elif word in ORDINALS:
        strength = 0.28 if word == 'first' else 0.65
        value = -strength * adaptation
    elif word in SCALES:
        value = 0.55
    elif token == ' ':
        if gap <= 3:
            value = -0.1
        elif line_age <= 2:
            value = -0.5 if previous.strip()[-1:].isalpha() else -0.05
        elif previous.rstrip().endswith(','):
            value = -1.6
        elif previous.isspace():
            value = -0.07
        else:
            value = -0.32 if gap == 4 else -0.65
    elif age == 0:
        value = -0.52 if token.startswith('<|') else 0.28
    elif age == 1 and previous == 'Title' and token == ':':
        value = -24.1
    if digit or numeral or word in NUMBER_WORDS:
        before, last = last, age
    if '\n' in token:
        newline = age
    return (doc, age + 1, last, before, token, newline), value

