        return 0.75  # Backslashes adjoining Markdown emphasis markers.
    if stripped == '\\x':
        return -0.15  # Hexadecimal escape introducer.
    if len(stripped) >= 2 and set(stripped) == {'·'}:
        return -0.75

    last = previous.decode('utf8', 'replace')[-1:] or ' '
    korean = 0xAC00 <= ord(last) <= 0xD7A3
    # Unicode Hangul syllables cycle through 28 final-consonant choices;
    # remainder zero means that there is no final consonant.
    vowel_final = korean and (ord(last) - 0xAC00) % 28 == 0
    if text in HONORIFIC:
        if last in COMMON_STEM_ENDINGS:
            return 5.75
        return 1.44 if vowel_final else 0.66
    if text in CONTRACTED:
        return 1.38 if vowel_final else 0.17
