        return 1.45 if vowel_final else 0.10
    if text == '리':
        if last in '이그저':
            return 2.25
        return 0.43 if vowel_final else 0.11
    if text == '던' and korean:
        return 0.51  # Past relative ending.
    if regex.fullmatch(r'\p{Katakana}', last):
        if text == 'レ':
            return 1.62
        if text == 'ラ':
            return 0.76
        if text in ('シ', 'ジ'):
            return 0.41
    if (last in 'เแโใไ' and regex.match(r'\p{Thai}', text)
            and not regex.match(r'\p{M}', text)):
        return 2.40  # Thai consonant following a preposed vowel sign.
    if text == '้า':
        return 1.27  # Thai tone mark followed by the aa vowel.
    return -0.0017


