    r'\b(?:for|foreach)\b\s*\(?\s*'
    r'(?:(?:var|let|const|int|auto|[A-Z]\w*)\s+)?'
    r'(\w+(?:\s*,\s*\w+)*|\([^)]*\))\s*$'
