        if bibliographic:
            return 10.0 if en_dash else 5.8
        return 1.9 if number < 20 else 3.0
    if re.search(r'\(\d{4}\),?\s*$', before):
        return 7.0 if en_dash else 4.5
    if 1890 <= number <= 2100:
        if en_dash:
            return 2.9 if before.endswith('(') else 1.6
        return 0.2
    if CITATION.search(before[-160:]) and number >= 5:
        return (6.0 if en_dash else 3.6) if number >= 80 else 1.4
    if re.search(r'\)\s*,?\s*$', before):
        return 2.8 if en_dash else 1.6
    if spaced:
        return 0.4 if en_dash else 0.09
    if en_dash:
        if number < 10:
            return 0.5
        return 1.8 if number < 100 else 3.0
    if before.endswith('\n'):
        return 0.1
    if number < 20:
        return 0.2
    if number < 150:
        return 0.65
    if not before or before[-1].isspace():
        return 1.5 if number < 500 else 1.0
    return 1.2 if before.endswith('(') else 0.4


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    mark = token.strip()
    value = 0.0
    m = re.search(r'(\d+)([ \t\u00a0]*)$', text)
    if token == '{':
        if re.search(r'\\cite[a-zA-Z*]*$', text):
            value = 5.0
        elif text.endswith('\\hspace'):
            value = 1.75
    elif m:
        before = text[:m.start()]
        if mark.startswith(('-', '–', '—', '−')):
            value = range_value(before, m[1], token, m[2])
        elif mark == '±':
            value = 1.9 if token.startswith(' ') else 3.65
        elif token in (' f', ' ff', 'ff'):
            if PAGE.search(before) or not before or before[-1].isspace():
                value = 1.1 if token == ' f' else 3.6
        elif token in ('][', ']{', '){'):
            value = 1.1
            if token == ']{' and re.search(r'\\cite[^{}]*$', text):
                value = 5.0
        elif CLOCK.search(text):
            if token == 'Z':
                value = 1.8
            elif token in (' +', '+'):
                value = 2.05
            elif token == ' UTC':
                value = 2.3
            elif mark.lower() in ('am', 'pm'):
                if token.startswith(' '):
                    value = 0.4 if mark == 'pm' else 0.0
                else:
                    value = 1.9 if mark == 'pm' else 0.9
            elif token in (' a', ' p'):
                value = 0.65
