programs.haiku:
"""Range separators between two numbers: a dash (or bracket boundary) that joins
a number to a following number, as in page, verse or citation ranges
(pp. 365-380, Job 32:21-22, Vol 3(2): 83-91, [77][78]). Such dashes fire most when
the range is a page/verse/reference range and least in arithmetic, codes and phone numbers."""
READS = ()

DASHES = "-–—"
BRACKET_JOINS = ("][", ")(", "){", "](", "]{")
MATH = ("=", "$", "+", "^", "\\")
PAGE_WORDS = ("pp", "p.", "Vol", "vol", "Pages", "pages", "Lines", "Col.")


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1].strip()
    prev = toks[-2] if len(toks) > 1 else ""
    if cur in BRACKET_JOINS and prev[-1:] in ")]}0123456789":
        return carry, 1.0
    if cur == "{" and any(c in prev for c in ("cite", "ref")):
        return carry, 3.0
    if not prev[-1:].isdigit():
        return carry, 0.0
    if not cur or cur[0] not in DASHES:
        return carry, 0.0
    # walk back over the number before the dash
    run, i = 0, len(toks) - 2
    while i >= 0 and toks[i].isdigit():
        run += 1
        i -= 1
    before = toks[i] if i >= 0 else ""
    window = "".join(toks[-20:])
    v = 0.1
    if cur[0] in "–—":
        v += 0.8
    if run == 1:
        v -= 0.3
    elif run == 3:
        v += 0.5
    if before == ":":
        v += 2.5
    elif before in (" ", ","):
        v += 0.5
    if any(w in window for w in PAGE_WORDS):
        v += 0.9
    if any(t.strip() in MATH for t in toks[-12:]):
        v -= 0.2
    return carry, max(v, 0.0)

