"""A surface-syntax approximation, strongest at the end of tool-call JSON.

Nested closing braces respond positively, especially with a final newline
and closing quote. Escaped line breaks in recent text increase that response.
Tool-protocol boundaries have smaller signed responses.
Repeated middle dots and literal null bytes are separate positive cases.
A document-opening Title: header has a large negative colon response;
a document-initial end-of-text marker is also negative.
The rest of the component's token-specific variation is left near zero.
"""
READS = ()

TOOL_BOUNDARIES = {
    '<tool_call>': 0.083,
    '</tool_call>': 0.109,
    '<tool_response>': 0.057,
    '</tool_response>': -0.056,
    '<|im_start|>': 0.034,
    '<|im_end|>': -0.022,
}


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    position = prefix.position
    doc = prefix.document_ids[-1]
    if text == '<|endoftext|>' and (
        position == 0 or prefix.document_ids[-2] != doc
    ):
        return None, -1.14
    if text == ':' and position >= 1:
        previous_begins_document = (
            position == 1 or prefix.document_ids[-3] != doc
        )
        if (
            previous_begins_document
            and prefix.document_ids[-2] == doc
            and prefix.token_strings[-2] == 'Title'
        ):
            return None, -3.9534
    if text in TOOL_BOUNDARIES:
        return None, TOOL_BOUNDARIES[text]
    if len(text) > 1 and set(text) == {'·'}:
        return None, 0.40
    if '\x00' in text:
        return None, 0.19

    value = 0.001
    if '}}' in text:
        value += 0.10
        if text.endswith('\n'):
            # Look back only within this document and a fixed-size window.
            recent = ''.join(
                prefix.token_strings[i]
                for i in range(max(0, position - 64), position)
                if prefix.document_ids[i] == doc
            )[-256:]
            value = 0.244 + 0.027 * min(recent.count('\\n'), 6)
            if '"' in text:
                value += 0.057
    elif '"' in text and any(c in text for c in ')]'):
        value += 0.04
    if '\\t' in text:
        value += 0.052
    return None, value

