READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, fragment = '', ''
    else:
        _, previous, fragment = carry
    token = prefix.token_strings[-1]
    lower = token.lower()
    word = lower.strip(' _\t\n')
    prev = previous.strip().lower()
    continued = bool(token and token[0].isalpha() and fragment)
    joined = (fragment + lower) if continued else lower
    match = re.search(r'[a-z]+$', joined)
    new_fragment = match.group()[-32:] if match else ''
    value = 0.0

    # These are spellings, not a general response to all numbers or plurals.
    if word in {'tuple', 'tuples'}:
        value = -4.6
    elif word in {'triple', 'triples'}:
        value = -5.5 if word == 'triple' else -8.0
    elif word in {'triplet', 'triplets'}:
        value = -3.8
    elif (word in {'pair', 'pairs'}
          or (continued and new_fragment in {'pair', 'pairs'})):
        value = -1.3 if word != 'pairs' else -1.7
        if prev == 'ordered':
            value = -4.5
        elif prev in {'possible', 'integer'}:
            value = -3.2
    elif word in {'duplicate', 'duplicates', 'duplication'}:
        value = -0.6
    elif word in {'multiple', 'multiples'}:
        value = -0.25
        if word == 'multiples':
            value = -2.9
        elif prev in {'a', 'any', 'some', 'no', 'integer', 'rational'}:
            value = -2.4
    elif word == 'of':
        if prev in {'multiple', 'multiples'}:
            value = -3.2
        elif prev in {'tuple', 'tuples'}:
            value = -2.5
        elif prev in {'pair', 'pairs', 'couple'}:
            value = -0.9
    elif continued:
        if (lower == 'uple' and fragment[-1:] not in 'aeiouy'
                and fragment[-1:].isalpha()):
            value = -8.0
        elif new_fragment in {'tup', 'quadrup'}:
            value = -6.0
        elif (lower in {'l', 'la', 'las', 'le', 'les', 'lo', 'los',
                        'ling', 'ple', 'ples', 'plet'}
              and re.search(r'(tup|trip|multip|dup)l', new_fragment)):
            value = -5.0
        elif new_fragment == 'trip' and lower == 'ip':
            value = -4.5
        elif lower == 'up':
            value = -0.8
        elif lower == 'ple':
            value = -1.3
        elif lower.isascii() and lower.isalpha():
            end = fragment[-1:]
            if lower.startswith('il'):
                if end in 'nd':
                    value = 2.4
                elif end in 'rl':
                    value = 0.7
            elif lower.startswith('ur') and end in 'dnl':
                value = 0.9
            elif lower.startswith(('ul', 'ip')) and end in 'dn':
                value = 0.4
            elif end == 'y' and lower.startswith('li'):
                value = 0.4
    return (doc, token, new_fragment), value

programs.haiku:
"""Counted-group words. The component reads the word being written and answers
negatively when it is a word for a group of items: 'triple' and 'tuple' (strongest),
their plurals, then 'pair' and 'multiple', and the ' of' right after 'multiple(s)' or
'pair' (as in "a multiple of 3", "a pair of dice"). Zero elsewhere."""
import re

READS = ()

WORD = re.compile(r"[a-z]+$")
STRONG = ("triple", "tuple", "triples", "tuples")
WORDS = {"pair": -1.0, "pairs": -1.5, "multiple": -0.4, "multiples": -3.0,
         "triplet": -4.0, "triplets": -4.0}
PARTIAL = {"tuple": -3.0, "triple": -2.0}   # the first pieces of these words, e.g. 'tup'


def word_value(word):
    if word.endswith(STRONG):
        return -5.0
    if word in WORDS:
        return WORDS[word]
    for whole, v in PARTIAL.items():
        if len(word) >= 3 and whole.startswith(word) and word != whole:
            return v
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.text_prefixes[-1].lower()
    m = WORD.search(text)
    word = m.group(0) if m else ""
    token = prefix.token_strings[-1].strip().lower()
    if token == "of" and len(prefix.token_strings) > 1:
        before = WORD.search(prefix.text_prefixes[-2].lower())
        previous = before.group(0) if before else ""
        if previous in ("multiple", "multiples"):
            return None, -3.0
        if previous in ("pair", "couple"):
            return None, -0.8
    return None, word_value(word)

programs.sol:
"""Approximate a short-spelling response: n--l negative, n--p positive.

Vowels may intervene. Patterns near a token's beginning are strongest;
longer endings weaken them. English frequency of the token and current
word fragment refines the estimate. Non-Han text is transliterated first.
Node package commands and repeated middle dots have separate positive rules.
Only the unfinished word is carried across tokens, resetting by document.
"""
from functools import lru_cache
import re
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
VOWELS = 'aeiouy'
PATTERN = re.compile(r'n([aeiouy]*)([lp])')


@lru_cache(maxsize=65536)
def roman(text):
    return anyascii(regex.sub(r'\p{Script=Han}', ' ', text)).lower()


@lru_cache(maxsize=65536)
def frequency(word):
    return zipf_frequency(word, 'en')


def strength(letter, vowels, before, after, vowel_prefix, word, token):
    if letter == 'p':
        if after > 1:
            return 0.04
        f = frequency(token.strip())
        if f < 4.0:
            return 0.535
        return 1.818 if f <= 4.4 else 0.56

    if before:
        if not vowel_prefix:
            return -0.035
        if after:
            return -0.093
        if frequency(token.strip()) <= 0.59:
            return -0.248
        return -3.134 if frequency(word) < 2.67 else -1.178
    if after > 1:
        return -1.167 if vowels == 'a' else -0.349
    if vowels == 'e':
        return -3.285
    if vowels == 'a':
        return -2.477 if frequency(word) < 1.94 else -1.253
    return -1.622 if not vowels else -0.755


def estimate(previous, current):
    joined = previous + current
    boundary = len(previous)
    tail = re.search(r'[a-z]+$', joined)
    next_word = tail.group()[-48:] if tail else ''
    matches = [m for m in PATTERN.finditer(joined) if m.end() > boundary]
    if not matches:
        return next_word, 0.0
    match = matches[-1]
    left, right = match.start(), match.end()
    while left and joined[left - 1].isalpha():
        left -= 1
    while right < len(joined) and joined[right].isalpha():
        right += 1
    before = max(0, match.start() - boundary)
    beginning = current[:before]
    vowel_prefix = bool(beginning) and all(c in VOWELS for c in beginning)
    value = strength(match[2], match[1], before, right - match.end(),
                     vowel_prefix, joined[left:right], current)

    # npm/pnpm package managers and the npx runner, including identifier suffixes.
    command = re.search(r'(pnpm|npm|npx)$', joined)
    if command:
        split = match.start() < boundary
        if command.group() == 'pnpm':
            value = 8.25 if split else 5.25
        elif command.group() == 'npm':
            value = 6.1 if split else 3.9
        else:
            value = 3.0
    return next_word, value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    word, value = estimate(previous, roman(text))
    if text and set(text) == {'·'} and len(text) >= 2:
        value = 1.337
    return (doc, word), float(value)

