Examples include a., b), p. and v.; line-leading labels are stronger.
Letters inside words, function arguments and algebraic expressions are
mostly excluded. The familiar copyright '(c)' marker is especially strong.
Small extra rules cover document onsets, pH, and prefixed biology acronyms.
The carry keeps a short text tail and resets at document boundaries.
"""
import re

READS = ()
ROMAN = re.compile(
    r'(?=.)m{0,3}(?:cm|cd|d?c{0,3})(?:xc|xl|l?x{0,3})'
    r'(?:ix|iv|v?i{0,3})\Z'
)
LABEL = re.compile(r'([^\W\d_]+)$')
LINE = re.compile(r'(?:^|\n|\\n)[ \t\r\xa0]*\(?$')
BLOCK = re.compile(r'(?:</?(?:p|li|div|br)>|//|#{1,6})[ \t]*\(?$')
BIOLOGY = {'DNA', 'RNA', 'PCR'}


def predict(token, previous, history, start=False):
