        if token.startswith('#'):
            return -1.2
        if token.strip().isdigit():
            return -0.6
        return -0.12 if token[:1].islower() else -0.28
    if token.strip() == 'pH':
        return -1.0
    match = LABEL.search(history)
    if not match:
        return 0.0
    label = match[1]
    head = history[:match.start()]
    if not label.islower() or (head and (head[-1].isalnum() or head[-1] == '_')):
        return 0.0
    single = len(label) == 1
    roman = ((len(label) > 1 or label in ('i', 'v'))
             and ROMAN.fullmatch(label) is not None)
    if not (single or roman or label in ('pp', 'ff')):
        return 0.0
