    return value * factor


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous, history = ('', '') if start else carry[1:]
    token = prefix.token_strings[-1]
    value = predict(token, previous, history, start)
    return (doc, token, (history + token)[-160:]), float(value)

