TECHNICAL = {'digital', 'scientific', 'medical', 'chemical', 'automotive',
             'healthcare', 'pharmaceutical', 'biomedical', 'aerospace'}
MEDIA = {'music', 'film', 'films', 'tv', 'television', 'news', 'press',
         'network', 'radio', 'magazine', 'magazines'}
INDUSTRY = {'research', 'design', 'engineering', 'technology', 'systems',
            'software', 'solutions', 'mining', 'energy', 'construction',
            'transportation', 'motors', 'insurance', 'financial', 'finance',
            'securities', 'investments', 'management', 'services', 'holdings',
            'holding', 'air', 'airlines', 'railway', 'industries', 'industrial',
            'consulting', 'toys', 'games', 'racing', 'sports', 'gas', 'oil',
            'electric'}
FUNCTION_WORDS = {'the', 'a', 'an', 'this', 'that', 'these', 'those', 'our',
                  'your', 'my', 'his', 'her', 'its', 'their', 'and', 'or',
                  'in', 'on', 'at', 'by', 'from', 'for', 'to', 'of', 'with',
                  'i', 'we', 'you', 'he', 'she', 'it', 'they'}

