    if word in LEGAL:
        return 1.4
    if word == 'enterprises':
        return 4.0
    if word == 'group':
        return 2.5
    if word == 'company':
        return 0.8
    if word in LABELS:
        return 5.2
    if word in TECHNOLOGY:
        return 5.7
    if word in TECHNICAL:
        return 3.8
    if word in {'bank', 'capital'}:
        return 3.0
    if word == 'international':
        return 3.0
    if word in MEDIA:
        return 1.4
    if word in INDUSTRY:
        return 1.3
