def context(tail, token):
    word = token.strip()
    match = re.search(r"([A-Za-z][A-Za-z'’&.-]*)[\s,]*$", tail)
    previous = match[1].rstrip('.') if match else ''
    name = (any(c.isupper() for c in previous)
            and previous.lower() not in FUNCTION_WORDS)
