What it does: this component is nearly silent inside a document, but fires on the very
first token of each document (the token right after <|endoftext|>, or the first token of a
packed row). There the model has no earlier context to look at, so its value depends only
on which token opens the document:

- a bare comment or heading marker ('#', '//') gives the strongest value (about 2.4);
- other comment openers ('##', '/*', a docstring quote) give about 1.9;
- the keyword that opens a source file ('package', 'from') gives about 3;
- code keywords ('import', 'def', 'using', 'const', 'export', 'class', '<?') give about 1.2;
- other heading-like openers ('**', '---', '#!', '#[') give about 0.6;
- C preprocessor lines ('#include', '#define', ...) are weak (0.3);
- a plain word opening prose gives about 0.1, and punctuation or a fragment about 0.

Everywhere else the program predicts 0. The real activation there is small, token-specific
noise (std about 0.04) that no simple concept here captures.
"""

READS = ()


def opener_value(token):
    """Activation predicted when this token is the first token of a document."""
    if token.strip() in ("#", "//"):
        return 2.4
    if token.startswith(("##", "//", "/*", '"""', "'''")):
        return 1.9
    if token in ("package", "from"):
        return 3.0
    if token in ("import", "def", "using", "const", "export", "class", "<?"):
        return 1.2
    if token.startswith(("**", "---", "#!", "#[")):
        return 0.6
    if token.startswith("#"):
        return 0.3
    if token[:1].isalpha():
        return 0.1
    return 0.0


def step(carry, prefix, upstream):
    # The first token of a row, or the first token after a document break, opens a document.
    opens = len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not opens:
        return carry, 0.0
    return carry, float(opener_value(prefix.token_strings[-1]))

