# Responses to epsilon: (word-initial preceding letter, internal letter).
EPSILON_AFTER = {
    'λ': (-2.8, -1.6),
    'γ': (-1.6, -0.8),
    'ν': (-1.5, -0.35),
    'θ': (-0.9, -0.9),
    'φ': (-0.9, -0.9),
    'τ': (-1.4, 0.0),
    'π': (-1.4, 0.0),
    'α': (-1.4, 0.0),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, old_bytes, de_strength = '', '', b'', 0.0
    else:
        _, previous, before, old_bytes, de_strength = carry
    raw = prefix.token_bytes[-1]
    text = raw.decode('utf-8', errors='replace')
    joined = (old_bytes + raw).decode('utf-8', errors='replace')
    # Restore a Greek letter whose two UTF-8 bytes were separate tokens.
    if len(raw) == 1 and old_bytes[-1:] in (b'\xce', b'\xcf'):
        if '\ufffd' not in joined:
            text = joined
