    initial = previous != p
    value, next_de_strength = 0.0, 0.0

    if text == 'ε':
        if p in ('δ', 'Δ'):
            if initial or p == 'Δ' or before.endswith('\n'):
                value = -10.1
            else:
                value = -9.2 if before == 'ν' else -5.8
            next_de_strength = value
        else:
            letter = p.lower() if p in ('Λ', 'Γ', 'Ν') else p
            at_start, inside = EPSILON_AFTER.get(letter, (0.0, 0.0))
            value = at_start if initial or p == 'Ν' else inside
    elif p in ('δ', 'Δ') and text in ('έ', 'ὲ', 'Ε', 'η', 'ή'):
        if text == 'έ':
            value = -4.3
        elif text == 'Ε':
            value = -5.4
        elif text == 'ὲ':
            value = -2.1 if initial else -0.7
        else:
            value = -1.3 if initial else 0.0
    elif text == 'δ' and p in ('ε', 'έ'):
        value = -3.0 if initial and p == 'ε' else -1.4
    elif text == 'έ' and p == 'λ':
        value = -1.25 if initial else -0.2
    elif text == 'λ' and p in ('ε', 'Ε'):
        value = -1.5 if initial else -0.6
    if text in ('ν', 'ι', 'ί'):
        value += 0.25 * de_strength
    elif text in ('ς', 'σ', 'λ', 'δ'):
        value += 0.45 * de_strength

    if joined.endswith('▼'):
        if not old_bytes or len(raw) == 1:
            value = -11.8
        else:
            value = -7.2 if previous.endswith('\n') else -4.0
    elif joined.endswith('▲'):
        value = -7.0 if previous and not previous.strip() else -4.0
    elif joined.endswith('▽'):
        value = -2.0
    elif joined.endswith('✅') and len(raw) == 1:
        value = 1.35
    elif text == '€' and p == 'â':
        value = -4.2 if initial else -2.9

    # E1 BC..BF is the partial UTF-8 spelling of Greek Extended characters.
    if old_bytes == b' \xe1' and len(raw) == 1:
        if raw == b'\xbc':
            value = 2.05
        elif b'\xbd' <= raw <= b'\xbf':
            value = 0.8
    return (doc, text, previous, raw, next_de_strength), value

