"""Candidate 7: spoken-register words: hedges, first words of quoted speech, dialogue pronouns."""
READS = ()
HEDGES = {"perhaps", "maybe", "hmm", "mmm", "huh", "uh"}
SPOKEN_OPENERS = {"uh", "um", "oh", "ah", "hey", "hi", "well", "look", "okay", "fine", "sorry",
                  "thank", "really", "actually", "yes", "yeah", "sure", "bye", "wow", "huh",
                  "what", "why", "how", "i", "you", "we", "me", "do", "are", "wait", "no", "come", "that"}
PRONOUNS = {"i", "you", "me", "we"}
SPOKEN_CJK = set("你我那这好吧吗啊嗎麽么呢是")
ELLIPSIS = {"...", "…", "……", "··"}

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = s.strip().lower().replace("'", "").replace("’", "")
    speech, prev_opened = carry if carry else (False, False)
    opened = False
    for ch in s:
        if ch == '"':
            speech = not speech
            opened = opened or speech
        elif ch in "“「":
            speech = True
            opened = True
        elif ch in "”」":
            speech = False
    if w in HEDGES:
        v = 1.3
    elif prev_opened and w in SPOKEN_OPENERS:
        v = 1.5
    elif speech and w in PRONOUNS:
        v = 0.4
    elif speech and any(ch in SPOKEN_CJK for ch in w):
        v = 0.8
    elif s.strip() in ELLIPSIS:
        v = 0.4
    else:
        v = 0.0
    return (speech, opened), v

