"""A short-spelling feature centered on the letter h.

It looks for h-onset fragments in the current token or across the previous
boundary.  hal/hab/hol tend positive; hop/hoc/hoff and hertz/Hz negative.
The three strengths distinguish unspaced pieces, space-prefixed pieces,
and continuations of a previous h. Longer endings weaken the response.
Digraphs and frequent English word-like pieces are discounted. This is a
local spelling approximation; it does not infer a word's meaning.
"""
from functools import lru_cache
import math
import unicodedata
from wordfreq import zipf_frequency

READS = ()

# Columns: unspaced token, space-prefixed token, h in previous token.
STRENGTH = {
    'ha': (.5, .9, 1.9),
    'hi': (1.25, .15, .4),
    'hal': (5.3, 2.9, 4.2),
    'hab': (5.2, 1.4, 4.5),
    'hol': (2.6, 1.0, 3.0),
    'haf': (2.5, 0.0, 4.0),
    'hav': (.2, .5, 2.1),
    'hau': (1.5, .4, 1.5),
    'hai': (0.0, 0.0, 1.1),
    'hou': (.15, 0.0, 2.6),
    'hil': (2.0, .3, 1.8),
    'hie': (.7, .35, 1.3),
    'hop': (-3.7, -3.9, -6.3),
    'hoc': (-4.4, -4.4, -5.6),
    'hoff': (-4.0, -3.6, -4.0),
    'hertz': (-7.5, -4.0, -7.5),
    'hz': (-5.7, -3.2, -4.0),
    'hg': (-1.7, 0.0, -4.2),
    'hf': (-1.0, -.85, -1.0),
    'hiz': (0.0, 0.0, -1.6),
}


def cluster(s):
    """Identify an h spelling and taper it as more letters complete it."""
    if s.startswith('hertz'):
        return 'hertz', math.exp(-len(s[5:]))
    if s.startswith(('hz', 'hg', 'hf')):
        return s[:2], math.exp(-len(s[2:]))
    if s.startswith('hoff'):
        return 'hoff', math.exp(-len(s[4:]))
    if s in ('ha', 'hi'):
        return s, .65
    stem, tail = s[:3], s[3:]
    if stem == 'hal':
        if not tail:
            return stem, 1.0
        if tail.startswith('t'):
            return stem, .8 * math.exp(-max(0, len(tail) - 3))
        if tail == 'l':
            return stem, .45
        return stem, .6 * math.exp(-.2 * len(tail))
    if stem in ('haf', 'hab'):
        ending = 't' if stem == 'haf' else 'en'
        return stem, 1.0 if not tail else (.5 if tail == ending else .1)
    if stem == 'hol':
        if tail.startswith('d'):
            return stem, .65 * math.exp(-max(0, len(tail) - 3))
        return stem, 1.0 if not tail else (.7 if tail == 't' else .15)
    if stem in ('hop', 'hoc'):
        if not tail:
            return stem, 1.0
        return stem, .35 if tail == 'ping' else (.7 if tail in ('p', 't') else .15)
    if stem in ('hav', 'hau', 'hai', 'hou', 'hil', 'hie'):
        return stem, math.exp(-.35 * len(tail))
    if stem == 'hiz':
        return stem, math.exp(-.8 * len(tail))
    return '', 0.0


def unaccent(s):
    return ''.join(c for c in unicodedata.normalize('NFD', s.lower())
                   if not unicodedata.combining(c))


def common_word_discount(s):
    return min(1.0, 10 ** (4.2 - zipf_frequency(s, 'en')))


@lru_cache(maxsize=65536)
def response(previous, token):
    previous, token = unaccent(previous), unaccent(token)
    values = [0.0]
    for i, ch in enumerate(token):
        if ch != 'h':
            continue
        group, amount = cluster(token[i:])
        if not group:
            continue
        before = token[i-1:i] if i else ''
        if before in ('c', 'p', 'w', 's'):
            amount *= .05
        piece = token.strip()
        short_hal = (group == 'hal' and piece.startswith('h')
                     and piece[3:] in ('', 'l', 't', 'te', 'ten'))
        if (token[:1].isspace() or i > 0) and not short_hal:
            amount *= common_word_discount(piece)
        if group in ('ha', 'hi'):
            clipped = token[:1].islower() and previous[-1:].isalpha()
            amount *= 1.0 if clipped else .1
        mode = 1 if token[:1].isspace() else 0
        values.append(STRENGTH[group][mode] * amount)
    if token[:1].isalpha():
        i = previous.rfind('h')
        fragment = previous[i:] if i >= 0 else ''
        if fragment.isalpha() and len(fragment) <= 4:
            group, amount = cluster(fragment + token)
            if group:
                before = previous[i-1:i] if i else ''
                if before in ('c', 'p', 'w'):
                    amount *= .05
                whole = (previous + token).strip()
                if before == 's' and whole.isalpha():
                    amount *= common_word_discount(whole)
                values.append(STRENGTH[group][2] * amount)
    return max(values, key=abs)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), float(response(previous, token))

