    token = prefix.token_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        first, uniform, pulse = token, True, initial_pulse(text)
        decoder = codecs.getincrementaldecoder('utf-8')('ignore')
        position = 0
    else:
        _, first, uniform, pulse, decoder, position = carry
        uniform = uniform and token == first
        position += 1
    characters = decoder.decode(prefix.token_bytes[-1])
    value = pulse if uniform else 0.002
    if not uniform:
        if text == '\u0651':  # Arabic consonant doubling (shadda).
            value = 0.29
        if characters and wringing_or_reeling(characters[-1]):
            value = 0.58
        if position == 1:
            previous = prefix.token_strings[-2].strip()
            if previous == '//' and text.strip() == '//':
                value = 0.75
            if previous == '<?' and text == 'php':
                value = 0.43
    return (doc, first, uniform, pulse, decoder, position), value

"""Sparse lexical and spelling rules; unlisted tokens predict zero.

Large negative responses occur on several literal East Asian graduation,
completion, and seniority forms, and on Greek consonant clusters ending in
pi (especially mu-pi). Some spikes occur halfway through UTF-8 characters.
These are spelling-sensitive rules, not a general classifier of meanings.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else b""
    raw = prefix.token_bytes[-1]
    text = raw.decode("utf-8", "replace")
    before = tail.decode("utf-8", "ignore")
    joined = tail + raw
    value = 0.0

    # Literal finish/graduate forms; not the unrelated word 毕竟 ('after all').
    if text in ("毕", "毕业"):
        value = -6.9
    elif text == "畢":
        value = -2.4
    elif text.startswith(("毕业", "畢業")):
        value = -3.5
    elif text.endswith(("毕", "畢")):
        value = -3.2
    elif text == "卒":
        value = -7.4
    elif text in ("辈", "輩"):
        value = -5.1
    elif text == "一辈子":
        value = -1.9
    elif text == "出身":
        value = -4.0
    elif text in ("满", "滿", "満"):
        value = -1.85

    # Greek μπ, σπ, κπ; distinguish word-initial from internal clusters.
    elif text == "π" and before:
        initial = len(before) < 2 or not before[-2].isalpha()
        if before.endswith(("μ", "Μ")):
            value = -11.2 if initial or before.endswith("Μ") else -5.8
        elif before.endswith(("σ", "Σ")):
            value = -3.8 if initial else -1.55
        elif before.endswith(("κ", "Κ")):
            value = -3.4

    # Continuation-byte tokens: unfinished 毕/築/stone-character prefixes,
    # the prefix shared by 졀–졿, and completion of 졸 ('jol', as in 졸업).
    elif len(raw) == 1:
        if joined.endswith("毕".encode()[:2]):
            value = -2.8
        elif joined.endswith("築".encode()[:2]):
            value = -1.3
        elif joined.endswith("碁".encode()[:2]):
            value = -6.3
        elif joined.endswith("졸".encode()[:2]):
            value = -6.5
        elif raw == "졸".encode()[-1:] and tail.endswith("졸".encode()[:2]):
            value = -5.45

    return (doc, joined[-24:]), value

"""A lexical approximation to molecular-biology and laboratory responses.

A short buffer joins subword tokens. Specific molecular terms, biological
stems, and selected unit spellings trigger positive responses. Split-word
endings often respond more strongly than unsplit words. This is not a
scientific-topic detector: other behavior, including negative responses,
is left at zero.
"""
import re
READS = ()


def response(text, token):
    if not token or not token[-1].isalpha():
        return 0.0
    match = re.search(r'[^\W\d_]+$', text)
    word = match[0] if match else ''
    w = word.lower()
    # Did earlier tokens supply part of this word?
    split = token.strip() != word
    # Nucleic-acid abbreviations, including an unfinished RN.
    rna = re.fullmatch(
        r'(m|t|r|si|sh|mi|micro|lnc|linc|circ|nc|Nc|ce|'
        r'ds|ss|sno|sn|pi|sa|vi|sc)?RN(A)?(s)?', word)
    if w == 'pretrna':
        return 6.6
    if word.islower() and re.fullmatch(
            r'(?:nc|lnc|linc|mi|si|sa|vi|m|t|r)rnas?', word):
        return 4.5
    if rna:
        kind, complete, plural = rna.groups()
        if not kind and not complete:
            return 8.3 if re.search(r'interfering RN$',text) else 1.4
        if not split:
            return 4.4
        if kind in ('r','t') and complete and not plural:
            return 9.8
        if kind == 'm':
            return 8.4
        if not complete:
            return 5.0
        if not kind:
            return 6.5 if plural else 4.4
        return 6.0
    if word.endswith(('DNA', 'DNAs')):
        if not split:
            return 2.2
        return 7.0 if word.endswith(('cDNA','rDNA')) else 3.9
    if word in ('miR', 'MiR'):
        return 3.2
    # Molecular parts and immunology vocabulary.
    if word.endswith(('SNP', 'SNPs')) and split:
        return 2.7
    if w.endswith(('nucleotide', 'nucleotides')) or text.endswith('核苷酸'):
        return 5.9
    if w in ('subunit', 'subunits'):
        return 8.8
    if w in ('acid', 'acids'):
        if re.search(r'(?:amino|nucleic|fatty)[ -]+acids?$', text, re.I):
            return 4.3
        return 1.4 if w == 'acids' else 1.0
    if text.endswith('酸'):
        return 5.0 if text.endswith(('脂肪酸','氨基酸','核酸')) else 0.7
    if w in ('plasmid', 'plasmids'):
        return 3.6
    if w.endswith(('lipid', 'lipids')):
        return 2.3 if split else 0.7
    if w in ('codon', 'codons', 'operon', 'operons'):
        return 5.8
    if w in ('exon', 'exons', 'intron', 'introns'):
        return 2.8
    if w in ('primer', 'primers'):
        return 5.2 if split else 1.2
    if w in ('isoform', 'isoforms'):
        return 5.0
    if w.endswith(('antibody', 'antibodies')):
        if split:
            return 5.0
        return 1.5 if w.endswith('antibodies') else 2.6
    if w.endswith('antib') and split:
        return 3.0
    if w.endswith(('antigen', 'antigens')):
        if split:
            return 1.5 if w.endswith('antigens') else 3.5
        return 0.9
    if w in ('cytokine', 'cytokines', 'chemokine', 'chemokines'):
        return 1.8 if split else 0.0
    if w in ('interferon', 'interferons') or word in ('IFN', 'IFNs'):
        return 3.0
    if re.fullmatch(r'Ig[AGMED]', word):
        return 3.8 if word == 'IgG' else 1.3
    if text.endswith('κB'):
        return 3.8
    if word in ('dN', 'dNTP', 'dNTPs', 'dT'):
        return 3.8
    if word in ('ATP', 'ADP', 'NAD', 'NADH', 'CoA'):
        return 1.8 if split else 1.2
    # Laboratory concentrations, acidity, mass, and prefixed units.
    # An escaped newline or a TeX command is not a measurement.
    if text.endswith('\\' + word):
        return 0.0
    if re.fullmatch(r'[mnpμµ]M', word) and not text.endswith(r'\nM'):
        return 4.4 if split else 2.0
    if word == 'pH':
        return 4.8 if split else 2.2
    if word in ('kDa', 'MDa'):
        return 6.1
    if word == 'kD':
        return 2.8
    if re.search(r'(?<![A-Za-z])[μµ]g$',text):
        return 2.6
    if re.search(r'(?<![A-Za-z])[μµ][lL]$',text):
        return 2.0
    if re.search(r'(?<![A-Za-z])[μµ]m$',text):
        return 2.7
    if word == 'mmol':
        return 0.7 if split else 0.0
    if re.search(r'(?<![A-Za-z])[pnumckμµ](?:mol|Ci|L|A|V|W|N|J|Pa)$',text):
        return 2.3 if split else 0.0
    if word == 'tsp':
        return 1.7
    if w.endswith(('peptide', 'peptides')):
        return 1.2
    if w.endswith(('oncogene', 'pseudogene')):
        return 3.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else b''
    tail = (tail + prefix.token_bytes[-1])[-160:]
    value = response(tail.decode('utf-8', 'replace'), prefix.token_strings[-1])
    return (doc, tail), value

programs.haiku:
"""Molecular-biology words. The component responds to the last piece of a nucleic-acid or
protein-chemistry term. Strongest on RNA compounds (RNA, mRNA, microRNA, lncRNA, siRNA), on
subunit, nucleotide, kDa, plasmid and codon; weaker on DNA (stronger in laboratory text than in
forensic or genealogy text), antibodies, IgG, interferon, amino and fatty acid, and micro-unit
abbreviations (μL, μg, μM). Near zero on other text.
A word is the letters since the last space or punctuation mark. "acid" counts strongly only after
amino, nucleic, fatty or a similar modifier.
"""
READS = ()

# prefixes that can precede "RNA" in a compound: mRNA, tRNA, siRNA, microRNA, lncRNA, ...
RNA_PREFIXES = ("", "m", "t", "r", "c", "e", "p", "h", "si", "sh", "ds", "ss", "ce", "mi", "sn",
                "hn", "pre", "pri", "circ", "micro", "lnc", "nc")
ACID_MODIFIERS = ("amino", "nucleic", "fatty", "ribonucleic", "deoxyribonucleic", "folic", "bile", "uric")
# words that mark a laboratory-biology document
LAB_WORDS = {"gene", "genes", "cell", "cells", "protein", "proteins", "sequence", "sequences",
             "expression", "pcr", "synthesis", "μl", "μg", "tissue", "mice", "mouse", "enzyme",
             "transcript", "transcription", "clone", "vector", "buffer", "assay", "samples",
             "bacterial", "bacteria", "cdna", "sequencing", "plasmid", "culture", "incubated"}
# stems found anywhere in a word, with their activation
STEMS = {
    "subunit": 7.0, "nucleotide": 6.0, "plasmid": 4.0, "codon": 4.5, "isoform": 4.5,
    "operon": 3.0, "exon": 1.7, "peptide": 1.5, "antibod": 2.9, "antigen": 1.5,
    "interferon": 3.5,
}
# whole words, lower case
WORDS = {"kda": 6.0, "kd": 1.0, "primers": 4.5, "primer": 1.0, "atp": 1.7, "igg": 3.0,
         "ifn": 3.0, "nad": 0.5}
# whole words, case matters
CASED = {"pH": 2.2, "mM": 1.9, "miR": 3.1}

def _trailing_word(piece):
    out = ""
    for ch in reversed(piece):
        if not ch.isalnum():
            break
        out = ch + out
    return out

def _value(word, last, lab):
    if word in CASED:
        return CASED[word]
    w = word.lower()
    base = w[:-1] if w.endswith("s") and not w.endswith("ss") else w
    if base.endswith("rna") and (base[:-3] in RNA_PREFIXES or base[:-3].endswith(("micro", "lnc"))):
        return 5.0
    if base.endswith("rn") and (base[:-2] in RNA_PREFIXES or base[:-2].endswith(("micro", "lnc"))):
        return 4.5 if lab else 0.4
    if base.endswith("dna"):
        return 3.1 if lab else 1.9
    if w.endswith("酸"):
        return 1.5  # Chinese for acid, e.g. 脂肪酸
    if base == "acid":
        return 4.2 if last.lower() in ACID_MODIFIERS else 1.2
    if w in WORDS:
        return WORDS[w]
    if len(w) == 2 and w[0] in "μµ":
        return 1.7  # micro-units: μL, μg, μM, μm
    best = 0.0
    for stem, v in STEMS.items():
        if stem in base and v > best:
            best = v
    return best

def step(carry, prefix, upstream):
    word, last, lab, prev_doc = carry if carry is not None else ("", "", 0, None)
    doc = prefix.document_ids[-1]
    if prev_doc is not None and doc != prev_doc:
        word, last, lab = "", "", 0
    piece = prefix.token_strings[-1]
    trail = _trailing_word(piece)
    if trail and trail == piece:
        word = word + piece
    else:
        if word:
            last = word
            if word.lower() in LAB_WORDS:
                lab += 1
        word = trail
    return (word, last, lab, doc), _value(word, last, lab >= 1)

programs.sol:
"""A sparse, lexical/contextual approximation, not a single semantic detector.

The large positive responses are Greek pi in prose and a few programming
identifiers in declaration/import contexts. Mathematical pi stays near zero.
Within Greek words, the preceding vowel and whether it starts the word matter.
Smaller rules cover pi's following Greek syllable, two other-script letter
pairs, class names, appellate 'App', pip, and structural tags.
Only a short byte/text tail is carried; a document boundary clears it.
"""
import unicodedata

READS = ()


def greek(char):
    return 'GREEK' in unicodedata.name(char, '') and char.isalpha()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, previous = b'', ''
    else:
        _, history, previous = carry
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1]
    before = history.decode('utf-8', 'ignore')
    after = (history + raw).decode('utf-8', 'ignore')
    added = after[len(before):]
    word = token.strip()
    prev = previous.strip()
    value = 0.0

    # Mathematical symbols occur amid numbers/Latin; prose has Greek letters.
    if added.strip() in ('π', 'Π'):
        letters = [c for c in before[-64:] if c.isalpha()]
        n_greek = sum(greek(c) for c in letters)
        prose = n_greek >= 4 and n_greek > len(letters) * 0.6
        nearby = [c for c in before[-16:] if c.isalpha()]
        prose |= sum(greek(c) for c in nearby) >= max(4, len(nearby) * 0.7)
        last = before[-1:] or ' '
        if added.strip() == 'Π':
            value = 5.5 if prose else 0.8
            if greek(last) and last.isupper():
                value = 1.3
        elif added[:1].isspace():
            value = 4.0 if prose else 0.0
        elif greek(last):
            decomposed = unicodedata.normalize('NFD', last)
            base = decomposed[0].lower()
            initial = len(before) < 2 or not before[-2].isalpha()
            if last == 'Υ':
                value = 14.0
            elif base == 'ο':
                value = -4.8 if last == 'ο' and not initial else 2.5
            elif base == 'ε':
                value = 9.4 if last in 'εΕ' else 1.8 if last == 'έ' else 5.6
            elif base == 'α':
                value = (7.8 if initial else 4.1) if last in 'αΑ' else 4.3
            elif base == 'υ':
                value = 10.4 if initial else 3.6
                if last not in 'υΥ':
                    value = 9.5 if 'DASIA' in unicodedata.name(last, '') else 6.7
            elif base == 'ι':
                value = 4.6 if '\u0342' in decomposed else 1.3
            elif base in ('μ', 'ω', 'σ'):
                value = 1.3 if base == 'μ' else 0.3
            else:
                value = 3.5
        elif prose and last in ' “«\n/':
            value = 4.0

    # The following Greek syllable retains a smaller response to pi.
    elif before.endswith(('π', 'Π')) and added in ('α', 'Α', 'ι', 'ρ', 'ο', 'ε'):
        if added in ('α', 'Α', 'ι'):
            value = 2.5
        else:
            value = 1.4 if added == 'ρ' else 0.6
    elif before.endswith('پ') and added == 'ی':  # Persian pi syllable
        value = 3.2
    elif before.endswith('п') and added == 'і':  # Ukrainian pi syllable
        value = 2.3

    # Familiar framework/application identifiers, with syntactic context.
    elif word == 'System':
        if prev == 'using':
            value = 10.75
        elif prev == 'namespace':
            value = 6.5
        elif prev in ('as', 'new', 'public', '='):
            value = 2.0
        elif '`' in previous:
            value = 5.0
        elif prev == '(':
            value = 2.3
        elif previous.isspace():
            value = 0.65
        elif prev == 'the':
            value = 2.1
    elif word.lstrip('./<') == 'App' or token in ('.app', '/app'):
        value = 1.0
        if previous == 'use' or prev == 'namespace':
            value = 19.0
        elif before.endswith('Open in'):
            value = 13.0
        elif before.endswith('Watch in'):
            value = 6.2
        elif prev == 'class':
            value = 3.8
        elif prev == 'new':
            value = 6.0
        elif prev == '{':
            value = 8.0
        elif prev in ('the', 'my', '('):
            value = 2.9
        elif token.startswith('.'):
            value = 4.8 if prev == 'android' else 3.3
        elif prev == 'use':
            value = 5.2
    elif word in ('Solution', 'Program') and prev == 'class':
        value = 3.5 if word == 'Solution' else 6.5
    elif token == 'pip':
        value = -5.7 if prev == '!' else -3.1
    elif token == ' -' and prev == '@@':
        value = 1.24
    elif token == '</think>':
        value = 0.87
    elif token == '</tool_call>':
        value = 0.26
    elif token == '··':
        value = -0.49

    return (doc, (history + raw)[-256:], token), value

programs.haiku:
"""Sparse spikes in one component of Qwen3-1.7B layer 1's MLP output.

The component is silent almost everywhere. It fires strongly on a few specific
tokens, and the program predicts those spikes from the words just before them:

1. Software namespace names right after the import keyword: `use App` and
   `namespace App` (PHP) are strongest (~20); `using System` (C#) ~11;
   `using namespace System` ~6.5; `class Program` ~7; `class Solution` ~4.
   Bare `App` / `System` in other software text get a small value.
2. The Greek letter pi (π, Π) used inside a Greek word (Υπηρεσία, Π at the start
   of a Greek line): about +4. After a/e (the prefixes απ-, επ-) it is larger;
   after o (τρό-π-ος) it is negative. In maths (2π) it stays 0.
3. The Python package name `pip` (also split as p|ip, as in `/pip/`): about -3.5 to -5.
4. The `.app` in Android imports (`android.app`): about +5.
5. Persian ی after پ (پی-ش): about +4.
6. The `</think>` tag: a small constant +0.9.

Everything else predicts 0. The replacement character (�) and small background
values are not modelled, and they carry much of the remaining variance."""

READS = ()

# Import keyword + name, and class + name, in code.
KEYWORD_NAMES = {
    ("use", " App"): 20.0,
    ("namespace", " App"): 20.0,
    ("using", " System"): 11.0,
    (" namespace", " System"): 6.5,
    (" class", " Program"): 7.0,
    (" class", " Solution"): 3.8,
    ("class", " Program"): 7.0,
    ("class", " Solution"): 3.8,
}
SOFTWARE_NAMES = {" App": 2.0, "App": 1.0, " System": 0.3, "System": 0.3}
PI_LETTERS = {"π", "Π", " π", " Π"}


def is_greek(text):
    return any("Ͱ" <= ch <= "Ͽ" or "ἀ" <= ch <= "῿" for ch in text)


def pi_value(prev):
    """Greek pi's activation, given the letter before it in the word."""
    if prev.strip() in ("ο", "ό"):
        return -3.0
    if prev.strip() in ("α", "ε", "ά", "έ"):
        return 6.0
    return 3.5


def step(carry, prefix, upstream):
    n = len(prefix.token_ids)
    if n < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2]
    recent = prefix.token_strings[max(0, n - 4) : n - 1]
    if (prev, cur) in KEYWORD_NAMES:
        return carry, KEYWORD_NAMES[(prev, cur)]
    if cur in SOFTWARE_NAMES:
        return carry, SOFTWARE_NAMES[cur]
    if cur in PI_LETTERS and any(is_greek(s) for s in recent):
        return carry, pi_value(prev)
    if cur.strip() in ("pip", "Pip"):
        return carry, -3.5
    if cur == "ip" and prev.lstrip("_/(. ") == "p":
        return carry, -5.0
    if cur == ".app" and any("android" in s for s in recent):
        return carry, 5.0
    if cur == "ی" and prev == "پ":
        return carry, 4.0
    if cur == "</think>":
        return carry, 0.9
    return carry, 0.0

"""layers.1.mlp.down_proj:1390 as a first-token-of-document feature.

What it does: this component is almost silent everywhere except at the first token
of a document (position 0 of a document, where the model's attention can only see
the token itself). There it writes a token-dependent amount, positive for most
ordinary words and code/markup tokens, negative for articles and a few prepositions.
The program predicts 0 at every other position and, at a document start, a value
chosen by the kind of token: the chat-template marker, linking words, articles, etc.
It does not know the exact per-token values (those vary a lot within each class).
"""
import unicodedata

READS = ()

CHAT_MARKER = "<|im_start|>"
ARTICLES_AND_PREPOSITIONS = {
    " the", " a", " an", " this", " that", " of", " to", " at", " after", " over",
    " in", " for", " on",
}
LINKING_WORDS = {
    " are", " were", " was", " be", " been", " being", " have", " has", " had",
    " may", " might", " can", " could", " should", " and", " or", " so", " as", " but",
    " with", " by", " from", " under", " between", " while", " not", " is",
}


def value(s):
    """Predicted activation for a token that opens a document, from its kind."""
    c = s.strip()
    if s == CHAT_MARKER:
        return 4.1
    if s.startswith("<|"):
        return 3.5
    if s in ARTICLES_AND_PREPOSITIONS:
        return -1.0
    if s in LINKING_WORDS:
        return 3.3
    if c == "":
        return 1.6
    if c.isdigit():
        return 0.7
    if len(c) == 1 and c.isupper() and c.isascii():
        return -0.9
    if c.isupper() and c.isascii() and len(c) > 1:
        return 3.7
    if c[:1].isupper() and c.isascii() and c.isalpha():
        return 1.2
    if c.isascii() and c.isalpha() and c.islower():
        return 2.0 if s.startswith(" ") else 1.4
    if c.isalpha():
        return 1.9
    if any(ch in "\n\r\t" for ch in s):
        return 3.2
    if c and all(unicodedata.category(ch)[0] in "PS" for ch in c):
        return 0.2
    return 2.1


def step(carry, prefix, upstream):
    starts_document = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document:
        return None, 0.0
    return None, float(value(prefix.token_strings[-1]))

programs.sol:
"""Negative lexical responses to web, week/weekend, weak and weed.

Bare roots respond more than longer tokens such as 'website'. Ordinary
English 'we' stays near zero, except at document start; recent German
function words and umlauts favor a negative we- response. Spelling
completions and the Chinese adjective 弱 ('weak') are also recognized.
Uncovered tokens get zero. This is a partial, spelling-sensitive account.
"""
import re

READS = ()
GERMAN = frozenset('''
der die das den dem des und nicht ist von zu mit auf für ein eine einer
auch als sich sie bei wie noch aus er es wir war werden hat haben sind
aber nur nach zum zur durch über
'''.split())
ENGLISH = frozenset('''
the and of to is are with from that this was have we our which you
'''.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    last, language, old_doc, position = carry or ('', 0.0, None, 0)
    if old_doc != doc:
        last, language, position = '', 0.0, 0
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    root = word.lstrip('._/-')
    value = 0.0

    if root in ('web', 'webs'):
        value = -3.0
        if text and text[0].isalnum():
            value = -5.0
        elif text.startswith('-'):
            value = -5.5
    elif root in ('week', 'weeks', 'weekend', 'weekends'):
        if root == 'weeks':
            value = -0.5
        elif root == 'weekends':
            value = -2.2
        elif root == 'weekend':
            value = -3.5
        else:
            spaced_lowercase = text.startswith(' ') and text.strip().islower()
            value = -1.6 if spaced_lowercase else -2.9
    elif root.startswith('weak'):
        value = -4.0 if root == 'weak' else -2.1
    elif root.startswith('weed'):
        value = -2.5
    elif word == '弱':  # The Chinese adjective 'weak'.
        value = -3.7
    elif root == 'we':
        joined = text and text[0].isalpha() and bool(last)
        value = -2.1 if joined else 0.03
        if word != root:
            value = -2.5
        if language > 1.5:
            value = -4.0 if joined else -4.6
        elif position == 0:
            value = -1.1
    elif text and text[0].islower() and last.endswith('we'):
        value = -1.3
        if text.startswith('ak') or text in ('b', 'bs', 'e'):
            value = -4.0
    elif text and text[0].islower():
        if last.endswith('weak') and text in ('ly', 'en', 'ens'):
            value = -2.5
        elif last.endswith('week') and text in ('s', 'end'):
            value = -3.5
        elif last.endswith('web') and text in ('s', 'en'):
            value = -2.5

    language = max(-3.0, min(6.0,
        language * 0.99 + (word in GERMAN) - (word in ENGLISH)))
    if any(ch in text.lower() for ch in 'äöüß'):
        language = min(6.0, language + 1.5)
    tail = re.search(r'[A-Za-zäöüß]+$', text)
    if tail:
        joined_tail = last + text if tail.start() == 0 else tail.group()
        last = joined_tail.lower()[-24:]
    else:
        last = ''
    return (last, language, doc, position + 1), value

programs.haiku:
"""Component layers.1.mlp.down_proj:1391: a negative detector for the spelling "we".

Almost every token leaves it at 0. It goes strongly negative on tokens that spell
the start of "web", "weak" or "weekend" (" web", "Web", "weak", " weakened", ...),
more mildly on "week" and "weeks", and on a bare "we" with no leading space, which
is usually a fragment of a longer word (German "we|isen", "we|il"). The spaced
English pronoun " we" is left at 0 because it averages about zero.
"""

READS = ()

STRONG = {"web", ".web", "/web", "-web", "weak", "weaken", "weakened", "weakening",
          "weaker", "weakness", "weekend"}
WEEK = {"week", "weeks"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if word in STRONG:
        value = -3.3
    elif word in WEEK:
        value = -1.5
    elif token == "we":
        value = -2.0
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Short-range, article-conditioned phrase responses.

Most predictions are zero. Large positives mark 'of/in the form', Romance
relative-pronoun constructions, possessives following articles, and
superlatives. Smaller rules cover relational nouns after English 'the'.
The noun rules are restricted to kinds, shapes, mathematical expressions,
ranges, purposes, and feelings; they are not a general noun detector.
Document boundaries discard the two-token history.
"""
READS = ()

ARTICLES = set('el la los las le les il i gli lo o os a as'.split())
CONTRACTIONS = set('al del da das do dos na nas no nos ao aos às '
                   'nel nella nelle nei negli sul sulla sulle '
                   'dei della delle degli alla alle ai dai agli '
                   'dal dalla dalle allo aux au du des'.split())
DEFINITE = ARTICLES | CONTRACTIONS
POSSESSIVES = set('mio mia miei mie tuo tua tuoi tue suo sua suoi sue '
                  'nostro nostra nostri nostre vostro vostra vostri vostre '
                  'meu minha meus minhas teu teus tua tuas '
                  'seu seus suas nosso nossa nossos nossas'.split())
SHAPE_OR_KIND = set('type style order shape'.split())
FORMULAS = set('equation equations formula formulas'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        before, earlier = '', ''
        value = -0.17
    else:
        _, before, earlier = carry
        value = 0.0
    word = token.strip().lower()
    prev = before.strip().lower()
    prev2 = earlier.strip().lower()
    article_boundary = before[:1].isspace() or not earlier

    if prev == 'the' and token.startswith(' '):
        value = -0.06
        if word == 'form':
            value = (10.0 if prev2 == 'of' else
                     4.2 if prev2 == 'in' else 1.8)
        elif word in SHAPE_OR_KIND:
            value = 2.4 if prev2 in {'of', 'in'} else 0.0
        elif word in {'kind', 'genus'}:
            value = 3.0 if word == 'kind' and prev2 == 'of' else 1.6
        elif word == 'ratio':
            value = 3.0 if prev2 == 'in' else -0.2
        elif word == 'range':
            value = 1.6 if prev2 in {'in', 'within'} else 0.1
        elif word in {'purpose', 'purposes'}:
            value = 1.6 if prev2 == 'for' else 0.1
        elif word == 'feeling':
            value = 3.1 if prev2 in {'have', 'had', 'has'} else 0.6
        elif word in FORMULAS:
            value = 1.5 if prev2 in {'of', 'by', 'using'} else 0.65
    elif prev == 'this' and word in {'kind', 'type'}:
        value = 2.6 if prev2 == 'of' else 0.7
    elif prev == 'a' and word == 'kind':
        value = 0.6
    if prev in DEFINITE and article_boundary:
        if word == 'que':
            value = (4.8 if prev in {'el', 'la', 'los', 'las', 'al', 'del'}
                     else 1.0)
        elif word in {'cual', 'cuales', 'quale', 'quali'}:
            value = 4.8
        elif word in POSSESSIVES:
            value = 1.7 if prev in {'il', 'lo', 'i', 'gli', 'del', 'della', 'dei',
                                       'al', 'alla', 'nella', 'nei', 'dai'} else 2.5
            if prev in {'do', 'da', 'dos', 'das', 'no', 'na', 'nos', 'nas', 'às'}:
                value = 3.5
        elif (word in {'plus', 'moins'} and prev in {'le', 'la', 'les', 'au', 'aux'}
              or word == 'más' and prev in {'el', 'la', 'los', 'las'}
              or word == 'mais' and prev in {'o', 'a', 'os', 'as', 'do', 'da', 'dos', 'das'}
              or word == 'più' and prev in {'il', 'la', 'i', 'le', 'gli'}):
            value = 2.5
        elif word == 'de' and prev in {'el', 'la', 'los', 'las'}:
            value = 2.6
        elif word in {'forma', 'forme', 'tipo'}:
            value = 3.4
        elif word == 'type' and prev in {'le', 'la', 'les', 'du', 'des', 'au', 'aux'}:
            value = 3.0
    # French lequel/laquelle/lesquels, including split suffixes.
    if (word in {'quel', 'quelle', 'quels', 'quelles'}
            and prev in {'le', 'la', 'les', 'du', 'des', 'au', 'aux'}):
        value = 3.8
    if word == 'qu' and prev in {'les', 'aux'} and not token.startswith(' '):
        value = 3.0 if prev == 'aux' else 0.75
    if word in {'els', 'elles'} and before == 'qu' and prev2 in {'les', 'aux'}:
        value = 9.0 if prev2 == 'aux' else 6.6
    if prev in {'à', 'a'} and word == 'la':
        value = 0.6
    if prev == 'ce' and word == 'qui':
        value = -0.8
    return (doc, token, before), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:1393 as a lexical rule: it fires on the word right after an article.
After "the" (or a Romance article), it is strongly positive on "form" (of the form) and on
relative pronouns (que, cual, quelle, lesquels), moderately on Romance possessives and "plus",
weakly on relational nouns (kind, purpose, range, ...), and slightly negative on a few nouns (case, law).
Zero everywhere else. Its value is the activation in the model's units."""
READS = ()

# Words that introduce a noun phrase: English "the" and the Romance articles.
ARTICLES = {" the", " el", " la", " los", " las", " le", " les", " il", " gli", " del", " della", " do", " da", " dos", " das", " nei", " nel", " al", " dei", " delle", "qu", "lesqu"}
# Relative pronouns (Spanish, French, Italian, Portuguese), split into pieces where the tokenizer splits them.
RELATIVE = {" que", " quel", " quelle", " quels", " quelles", " cual", " cuales", " quale", " quali",
            " lesquels", " lesquelles", " els", " elles", "els", "elles", "quel", "quelle", "quali", "quale", "cuales", "cual"}
# Possessives and comparatives that follow such an article (la sua, el seu, les plus).
POSSESSIVE = {" sua", " suo", " seu", " seus", " sue", " mia", " mio", " meu", " nossa", " nostra", " tua", " tuo",
              "sua", "suo", "seu", " plus", " más", " mais", " moins", " de"}
# Nouns that take an "of" complement after "the" (the form of, the kind of, the purpose of ...).
RELATIONAL = {" kind", " style", " purpose", " purposes", " sense", " range", " order", " season", " year",
              " equation", " formula", " art", " genus", " type", " tipo", " box", " sake", " feeling", " exception"}

def step(carry, prefix, upstream):
    """Activation guess for one token: nonzero only when it directly follows an article."""
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if prev not in ARTICLES:
        return None, 0.0
    if cur == " form":
        return None, 4.8
    if cur in RELATIVE:
        return None, 4.9
    if cur in POSSESSIVE:
        return None, 2.0
    if cur in RELATIONAL:
        return None, 0.9
    if prev == " the" and cur in {" case", " law", " hospital", " like", " thing"}:
        return None, -0.5
    return None, 0.0

programs.sol:
"""A spelling-sensitive detector centred on bei, bij and pri-like syllables.

Short German bei forms are strongly negative; corresponding Cyrillic/Dutch
forms and a few similar syllables are weaker. Split spellings also count:
be + i..., Czech př + i/í, and Cyrillic б/п + front vowels, for example.
Whole longer words containing these letters are not treated alike.
Arabic/Persian and Slavic vowel contrasts sometimes give a positive signal.
Only the previous token is retained, and document boundaries reset it.
"""
READS = ()


def response(previous, token):
    s = token.strip().lower()
    p = previous.strip().lower()
    free = (token[:1].isspace() or not previous
            or not previous[-1:].isalpha())
    initial = previous[:1].isspace() or previous[:1].isupper()
    if s == 'bei':
        if free or token[:1].isupper():
            return -12.8 if token.lstrip()[:1].isupper() else -11.7
        return -4.6
    if s == 'beim':
        return -7.5
    if s == 'dabei':
        return -5.3
    if s == 'bey':                 # Historical spelling of bei.
        return -3.3
    if s == 'bij':
        return -8.0 if free else -2.0
    if s == 'при':
        return -5.9 if free else -2.5
    if s == 'pri':
        return -1.7 if free else -0.2
    if s == 'با':
        return -4.1 if free else -2.1
    if s == 'بر':
        return 3.0 if free else 1.6
    if s == 'bài':
        return -5.8
    if s in ('př', 'przy'):
        return -1.3
    if s == 'пи':
        return -2.2 if free else -0.3
    if not token or token[0].isspace():
        return 0.0

    # A new piece completes a short labial-onset spelling.
    if p.endswith('be') and s.startswith('i'):
        if p == 'be' and initial:
            return -11.8 if s == 'im' else -5.5
        return -2.8
    if p == 'b' or p.endswith('.b'):
        if s.startswith('ij'):
            return -10.5 if previous[-1:] == 'B' else -1.8
        if s.startswith('ai'):
            return -5.3
    if p.endswith('п') and s == 'ри':
        return -7.7 if p == 'п' else -3.7
    if p == 'př':
        if s in ('i', 'í'):
            return -7.8 if s == 'i' else -4.0
        if s.startswith('i'):
            return -2.7
        if s in ('e', 'át'):
            return 4.2
    if p in ('б', 'п'):
        if s == 'і':
            return -4.4 if initial else -1.7
        if s == 'и':
            return -2.8 if initial else -0.8
    if p == 'ب' and s == 'ای':
        return -5.2
    if p == 'بر' and s == 'ای':
        return -3.1
    if p == 'پ' and s == 'ر':
        return 5.2
    # Thai short-i sign following the leading-e vowel spelling.
    if s == 'ิ' and p.startswith('เ'):
        return -6.5 if p[-1:] in 'บปพฟภ' else -3.5
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, token), response(previous, token)

"""A coarse approximation of formatting and short grammar pulses.

Bare bullets give positive pulses, strongest on spaces and headings. Forum
labels and count/date separators also pulse. The space pulse is stronger early
in a document and weaker in densely spaced lists. Negative rules recognize
'you + auxiliary/ever + been', capitalized 'You + auxiliary + the', and tokens
made of repeated middle dots. Initial tokens get a small shape/frequency
adjustment. Other positions predict zero. State resets at document boundaries.
"""
from functools import lru_cache
from calendar import month_abbr, month_name
from wordfreq import zipf_frequency

READS = ()
LINKS = {'are', 'were', 'have', 'had', 'ever', "'re", '’re', "'ve", '’ve'}
FORUM_FIELDS = {'replies', 'posts', 'member', 'page', 'pg', 'date'}
COUNT_DATE_FIELDS = {'replies', 'posts', 'views', 'joined', 'posted', 'date'}
MONTHS = set(month_abbr[1:]) | set(month_name[1:])


@lru_cache(maxsize=4096)
def initial_value(token):
    word = token.strip()
    if token.startswith('<|'):
        return 0.0
    if word.startswith('#'):
        return -0.45
    if len(word) <= 1:
        return -0.04
    if word.casefold() == 'the':
        return -0.34
    return -0.23 if zipf_frequency(word, 'en') <= 6.25 else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, -10000, 10000)
    _, previous, before_previous, position, last_bullet, bullet_gap = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    value = initial_value(token) if position == 0 else 0.0

    # Only a bare bullet token, not an inline space-prefixed bullet.
    if previous == '•':
        if token == ' ':
            if position <= 14:
                value = 6.0
            elif position <= 77:
                value = 3.9
            else:
                value = 1.9 if bullet_gap <= 38 else 3.0
        elif word and set(word) == {'#'}:
            value = 2.4 if len(word) == 1 else 18.0 / len(word)**2
        elif position <= 2:
            value = 5.2
        elif len(word) == 1 and word.isascii() and word.isupper():
            value = 0.5
        elif position <= 33:
            value = 0.65
        else:
            value = 0.08
    elif previous == '-':
        if token == ' ':
            value = 0.7 if position <= 15 else 0.35
        elif position <= 3 and token.startswith(' '):
            value = 1.0

    # Numeric metadata can begin on the separator, not on the field's name.
    field = previous.strip()
    prior_field = before_previous.strip().casefold()
    if previous.strip() == '•' and word.casefold() in FORUM_FIELDS:
        value = 2.5
    if before_previous.strip() == '•':
        if word == ':' and field.casefold() in COUNT_DATE_FIELDS:
            value = 2.0
        elif token == ' ' and (field in MONTHS or field.casefold() in {'page', 'pg'}):
            value = 2.0
    if word == ':' and field == 'Updated' and before_previous.strip() == 'Last':
        value = 3.0
    if token == ' ' and field == ':' and prior_field in COUNT_DATE_FIELDS:
        value = 1.0

    if before_previous.strip().casefold() == 'you':
        if previous.strip() in LINKS:
            if word == 'been':
                value = -0.81
            elif before_previous.strip() in {'You', 'YOU'} and word == 'the':
                if previous.strip() in {'are', 'were', "'re", '’re'}:
                    value = -5.0 if position <= 6 else -1.3
                else:
                    value = -0.4
    if token and set(token) == {'·'} and len(token) >= 2:
        value = -2.1

    if token == '•':
        bullet_gap = position - last_bullet
        last_bullet = position
    return (doc, token, previous, position + 1, last_bullet, bullet_gap), value

programs.haiku:
"""Layer-1 MLP down_proj component 1396: a small concept-level guess.

The component's activation is small and noisy (std about 0.05) and rarely large.
Its sign and size depend only weakly on what the token is. Ranked by how well they
line up with the activation, the concepts we found are:
  * the first token of a document (right after <|endoftext|>): positive, about +0.08;
  * CJK characters: slightly positive;
  * ASCII letter words and word-internal fragments: slightly negative;
  * digits and leading-space tokens: slightly positive;
  * code-like punctuation and identifiers: slightly negative.
Everything else is 0. The weights were fitted on 1M tokens of training text
(ordinary least squares); they are small, so the program is close to zero almost everywhere.
"""

import re

READS = ()

BOUNDARY_TOKEN = "<|endoftext|>"
BOUNDARY_MEAN = 0.08
CJK_WEIGHT = 0.007
DIGIT_WEIGHT = 0.004
SPACE_WORD_WEIGHT = 0.005
ALPHA_WEIGHT = -0.005
CODE_WEIGHT = -0.002
CODE_PATTERN = re.compile(r"[{}();=<>\[\]_]|\.\w")


def _is_cjk(s):
    return any("一" <= ch <= "鿿" for ch in s)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if len(prefix.token_strings) >= 2 and prefix.token_strings[-2] == BOUNDARY_TOKEN:
        return None, BOUNDARY_MEAN
    st = s.strip()
    value = 0.0
    if _is_cjk(s):
        value += CJK_WEIGHT
    if st.isdigit():
        value += DIGIT_WEIGHT
    if s.startswith(" "):
        value += SPACE_WORD_WEIGHT
    if st.isalpha():
        value += ALPHA_WEIGHT
    if CODE_PATTERN.search(s):
        value += CODE_WEIGHT
    return None, value

programs.sol:
"""A tokenizer-sensitive spelling model, usually predicting nearly zero.

Short pr/pre/pron/prz fragments tend to give negative continuation pulses,
especially Cyrillic пр. Selected ier-led pieces give positive pulses:
strongest after an exact tt fragment, as in some splits of prett-ier. Premier and frontier
spellings are positive too. Capitalization and leading separators provide
word-onset cues. These are spelling rules, not a general rule about meaning.
"""
from functools import lru_cache
from anyascii import anyascii
import regex as re

READS = ()


@lru_cache(maxsize=32768)
def spelling(text):
    return anyascii(text).lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    current = spelling(text)
    match = re.search(r"[a-z]+$", spelling(previous).strip())
    stem = match[0] if match else ""
    continuation = bool(text) and not text[0].isspace()
    marked_onset = bool(previous) and (
        not previous[0].isalpha() or previous[0].isupper()
    )
    value = 0.002

    # Complete spellings can carry the same positive response as split endings.
    if "premier" in current:
        value += 2.406
        if text.strip()[:1].isupper():
            value += 2.290
    if "frontier" in current:
        value += 4.799

    if continuation:
        if current.startswith("ier"):
            if stem.endswith("m"):
                value += 2.566
            if stem.endswith("rn"):
                value += 2.780
            if stem.endswith("tt"):
                value += 2.979
            if stem == "tt":
                value += 6.335
        if current.startswith("tier") and stem.endswith("pret"):
            value += 4.146
        if stem.endswith("front") and (
            current.startswith(("ier", "era")) or current == "-line"
        ):
            value += 5.243

        # A letter-led continuation, or a hyphenated extension of the prefix.
        letter_piece = "a" <= current[:1] <= "z" or current.startswith("-")
        if letter_piece:
            if stem == "pr":
                if marked_onset:
                    value -= 0.707
                if re.search(r"\p{Script=Cyrillic}", previous):
                    value -= 1.669
                if "r" in current:
                    value += 1.502
            if stem == "pre":
                if marked_onset:
                    value -= 0.551
                if current == "-order":
                    value -= 7.310
                elif current == "order":
                    value -= 4.811
            if stem == "pron" and marked_onset:
                value -= 3.583
            if stem == "prz":
                value -= 1.835

    return (doc, text), value

"""Approximate a new-variable assignment cue, plus mixed indentation.

The large positive response is for assigning to a bare name, especially in
an explicit declaration. Field updates, parameter lists, equations and
unspaced equals signs are usually much weaker. Recent code-like text helps
distinguish a one-letter code variable from a mathematical symbol. A second
response detects tab/space indentation, including numbered source listings.
Only the previous token and the last 250 characters are retained.
"""
import re

READS = ()
NAME = r'[A-Za-z_$][A-Za-z0-9_$]*'
TYPE = (
    r'(?:int|auto|float|double|long|bool|string|char|short|'
    r'[A-Z][A-Za-z0-9_]*|[A-Za-z0-9_]+_t|[\w:]+<[^;=]+>)'
)
DECLARATION = re.compile(
    r'(?:(?:var|let|const|my|local|val)\s+(?:mut\s+)?'
    r'|(?:(?:const|static|public|private|final|unsigned|signed)\s+)*'
    + TYPE + r'\s+)' + NAME + r'\s*$'
)
CODE = re.compile(
    r'\b(?:def|return|import|print|while|function|const|var|let)\b'
    r'|;|\{\s*\n|\w\.\w+\('
)
STRONG_CODE = re.compile(
    r'\b(?:def|import|print)\b|;\s*(?:\n|$)|\w\.\w+\('
    r'|\b(?:map|input|open|range|len)\('
)


def assignment(token, tail):
    sign = token.strip()
    if sign.startswith('<-'):
        return 1.15
    if not (sign.startswith(':=') or sign.startswith('=')):
        return None
    if sign.startswith(('==', '=>')):
        return None

    line = re.split(r'\n|\\n', tail)[-1].replace('\\t', '\t')
    line = re.sub(r'\\+\$', '$', line).replace('`', '')
    line = re.sub(r'^\s*\d+\t', '', line)
    line = re.sub(r'^\s*[+-]\s*', '', line).rsplit(';', 1)[-1]
    if not line.strip():
        return -0.5
    match = re.search('(' + NAME + r')\s*$', line)
    if not match:
        return -0.1
    name = match.group(1)
    before = line[:match.start()].rstrip()
    member = before.endswith(('.', '->', '::'))
    if sign.startswith(':='):
        return 0.12 if member else 1.3
    if member:
        return 0.12
    if re.match(r'\s*(?:where|on|and|or)\b', line, re.I):
        return -0.08
    # Prepositions and a closing dollar delimiter suggest prose or mathematics.
    if re.match(r'\s*(?:at|from|for|in|with|to|as|of|by)\s+', line, re.I):
        return 0.05
    if name.endswith('$'):
        return 0.05

    bare = not before.strip(' \t/*+-|')
    strong_code = bool(STRONG_CODE.search(tail))
    if not token.startswith(' '):
        if bare and strong_code:
            return 0.8
        return 0.04
    if DECLARATION.fullmatch(line.strip()):
        return 1.1 if len(name) < 4 else 1.45
    if DECLARATION.search(line) and '(' in line:
        return 0.37
    if any(c in line for c in '(=+\\'):
        return 0.05
    if not bare:
        return 0.3
    if len(name) == 1:
        code = strong_code or (line[:1].isspace() and CODE.search(tail))
        return 1.25 if code else 0.45
    return 0.6 if name[0].isupper() else 1.2


def indentation(token, previous):
    if not token.isspace() or '\n' in token or '\r' in token:
        return None
    spaces, tabs = token.count(' '), token.count('\t')
    if spaces and tabs:
        return min(0.8, 0.4 + 0.02 * spaces)
    if tabs:
        if previous.isdecimal():
            return 0.13 if tabs == 1 else 0.45
        return 0.65 if previous.isspace() and ' ' in previous else -0.015
    if '\t' in previous and previous.isspace():
        return 0.8
    return -0.025 if len(token) > 1 else -0.004


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous = '', ''
    else:
        _, tail, previous = carry
    token = prefix.token_strings[-1]
    value = assignment(token, tail)
    if value is None:
        value = indentation(token, previous)
    if value is None:
        value = 0.2 if token.strip() in ('+=', '-=', '*=', '/=') else -0.004
    return (doc, (tail + token)[-250:], token), float(value)

"""Approximate document-start and multiline-code-opening responses.

Training activations concentrate at document beginnings: usually a negative
pulse, continuing through identical repetitions of the opening token.
Its gain depends on token shape, script, whitespace and broad word classes;
the end-of-text marker is a positive exception. Later text is normally zero,
with smaller negative pulses at multiline bracket/colon openings and
underscore rules. Shape-based gains omit substantial token-specific detail.
"""
import re
import regex

READS = ()
PREPOSITIONS = frozenset('''of in on at by from with for to into onto
    over under after before between through during against without within
    across among around about'''.split())
BLOCK = re.compile(
    r'^\s*(?:async\s+)?(?:if|elif|else|for|while|def|class|try|except|'
    r'finally|with|case|switch)\b'
)


def opening_value(text):
    s = text.strip()
    if s == '<|im_start|>':
        return -5.8
    if s == '<|endoftext|>':
        return 3.7
    if not s:
        return (-2.24 - 0.37 * min(len(text), 6) * ('\n' not in text)
                - 1.22 * ('\n' in text) + 1.35 * (text.count('\n') > 1)
                - 2.23 * ('\t' in text))
    if s.isdigit():
        return -2.5 + (0.26 * int(s) if len(s) == 1 and s.isascii() else 0)
    if s == '_' and text.startswith(' '):
        return -0.8
    if not any(c.isalnum() for c in s):
        return (-2.6 + 1.6 * (s[-1] in '([{')
                + 0.53 * (s[-1] in ')]}')
                + 1.27 * (text.count('\n') > 1))
    latin = s.isascii() and s.isalpha()
    if latin:
        value = -4.0
        if len(s) == 1:
            value -= 2.0 + 0.9 * s.isupper()
        elif len(s) < 4:
            value -= 1.4
        value -= 0.15 * s[0].isupper()
    elif s.isascii():
        value = -3.75  # Mixed letters and punctuation, e.g. identifiers.
    else:
        value = -6.0 + 1.6 * bool(regex.search(r'\p{Script=Han}', s))
    value += 1.15 * text.startswith(' ')
    value += 1.9 * (s.lower() == 'the')
    value += 1.6 * (s.lower() in PREPOSITIONS)
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        first, repeated, line = prefix.token_bytes[-1], True, ''
    else:
        _, first, repeated, line = carry
        repeated = repeated and prefix.token_bytes[-1] == first
    current_line = line + token
    if repeated:
        value = opening_value(token)
    else:
        value = 0.0
        ending = token.rstrip('\r\n\t ').rstrip('\\')
        if '\n' in token and ending.endswith(('{', '(', '[')):
            value = -1.1 - 0.15 * (token.count('\n') > 1)
        elif token.endswith('\\') and ending.endswith(('{', '(', '[')):
            value = -1.6 if token.startswith(' ') and '{' in token else -0.3
        elif ('\n' in token or token.endswith('\\')) and ending.endswith(':'):
            value = -0.75 if (BLOCK.match(current_line)
                              or '):' in token or "':" in token) else -0.05
        elif token.strip() == '_' and current_line.count('_') >= 3:
            if not current_line.replace('_', '').strip():
                value = -0.8
    line = current_line.replace('\\n', '\n').rsplit('\n', 1)[-1][-256:]
    return (doc, first, repeated, line), float(value)

"""A local repetition detector, with a larger negative response for Han text.

It compares adjacent alphabetic tokens, ignoring case and leading code
punctuation. Exact repeats are stronger than case/punctuation variants.
It also recognizes repeated final Han characters, escaped quotes, non-ASCII
punctuation and symbols, carriage returns, and weak comma-separated echoes.
Digits and escaped newlines do not count as repeated words.
The literal document-opening field ``Title:`` has a separate positive value.
"""
import regex
import unicodedata
from functools import lru_cache

READS = ()


@lru_cache(maxsize=8192)
def clean(text):
    return text.strip().lstrip('.,;:/_([<{=+-&')


def repetition(text, previous):
    if text == previous == '\r':
        return -0.85
    a, b = clean(text), clean(previous)
    if not a or not b:
        return -0.001
    if a.casefold() == b.casefold() and a.isalpha():
        if regex.search(r'\p{Script=Han}', a):
            return -1.2
        if regex.search(r'[\p{Hiragana}\p{Katakana}\p{Hangul}]', a):
            return -0.9
        if not regex.fullmatch(r'\p{Script=Latin}+', a):
            return -0.4
        if a != b or text.strip() != previous.strip():
            return -0.3
        if text[:1].isspace() != previous[:1].isspace():
            return -0.32
        return -0.75
    if len(a) == 1 and regex.fullmatch(r'\p{Script=Han}', a):
        if b.endswith(a):
            return -0.7
    if a == b and a in ('\\"', "\\'"):
        return -0.85 if text == previous else -0.3
    if a == b and not a.isascii() and '\ufffd' not in a:
        if all(unicodedata.category(c)[0] in 'PS' for c in a):
            fullwidth = any(unicodedata.east_asian_width(c) == 'F' for c in a)
            return -0.15 if fullwidth else -0.65
    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ()
    value = repetition(text, history[-1]) if history else -0.001
    if len(history) >= 2 and history[-1].strip() in (',', ';', ':'):
        if clean(text).casefold() == clean(history[-2]).casefold():
            if regex.fullmatch(r'\p{Script=Latin}+', clean(text)):
                value = -0.08
    if history == ('Title',) and text == ':':
        value = 4.37
    return (doc, (history + (text,))[-3:]), value

"""A sparse detector for written deliverables and requests to produce them.

Positive cues include essays, assignments, writing, requested word counts,
and an article following a production verb (especially at a clause opening).
A few document-preview and tutoring-site cues supplement this core pattern.
Two instruction lead-ins ("you will", "what are the") also receive a boost.
The numbers are rounded training estimates. Negative values and most small,
context-dependent background activity are deliberately left unmodeled.
"""
import re

READS = ()
WRITE = {'write', 'writing', 'compose', 'composing', 'draft', 'drafting'}
CREATE = {'create', 'generate', 'build', 'develop', 'implement', 'craft',
          'design', 'construct', 'produce', 'prepare'}
SUBMIT = {'submit', 'complete', 'deliver', 'insert', 'conduct', 'post'}
NUMBERS = {'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight',
           'nine', 'ten', 'hundred', 'thousand'}
WORK = {'essay', 'essays', 'assignment', 'homework', 'paper', 'papers',
        'writing'}

# Phrases describing previews, attachments, and worked solutions.
DOCUMENT_PHRASES = {
    'this preview': 2.8,
    'preview shows': 0.85,
    'shows pages': 2.5,
    'document pages': 2.5,
    'shows page': 2.5,
    'full document': 1.95,
    'solution summary': 2.25,
    'the attached': 1.0,
    'attached files': 1.0,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', True, '')
    _, previous, before, previous_start, text = carry
    raw = prefix.token_strings[-1]
    t, p, q = raw.strip().lower(), previous.strip().lower(), before.strip().lower()
    at_start = not text.strip() or bool(re.search(r'[\n.!?]\s*$', text))
    tail = (text + raw)[-100:]
    lower = tail.lower()
    number = p.isdecimal() or p in NUMBERS
    value = DOCUMENT_PHRASES.get(p + ' ' + t, 0.0)

    if t in {'a', 'an'} and p in WRITE | CREATE | SUBMIT:
        value += 1.15 if p in WRITE else 0.4
        if previous_start:
            value += 0.9
    if t in {'word', 'words', '-word'} and number:
        value += 0.75 if t == 'word' else 2.2
        if re.search(r'\b(write|writing|give|introduction|essay)\b', lower):
            value += 1.65
    page_units = {'page', 'pages', 'страниц', 'страницы', '페이지'}
    if t in page_units and number:
        value += 0.95
    if t in {'字', '字符'} and number:
        value += 1.7
    if t in {'essay', 'essays'}:
        value += 1.6
        if p in {'an', 'a', 'words', '-word', 'contrast', 'comparative'}:
            value += 0.9
    if t in {'paper', 'papers'}:
        value += 0.25
        if p in {'research', 'term', 'your', 'academic'}:
            value += 2.9
    if t in {'assignment', 'assignments', 'homework'}:
        value += 0.65
        if p in {'your', 'the', 'written', 'math', 'words'}:
            value += 0.95
    if t == 'writing':
        value += 0.6
        if p in {'am', 'your', 'creative', 'resume', 'nursing'}:
            value += 0.7
    if t in {'write', 'writes', 'writer', 'writers', 'tutor', 'tutors'}:
        value += 0.27
    if t == 'prompt':
        value += 0.3
    if t in {'写', '写作', '撰写'}:
        value += 0.65
    if p in WORK:
        value += 0.15
    if t in {'help', 'services'} and p in WORK:
        value += 2.2
    if t == 'on' and p in {'essay', 'assignment'}:
        value += 1.45

    if t == 'will' and p == 'you':
        value += 0.55
    if t == 'the' and p == 'are' and q == 'what':
        value += 0.85

    if t == 'solution' and re.search(r'completed\s+solution$', lower):
        value += 2.0
    if lower.endswith('brainmass'):
        value += 7.0
    if t == '.com' and lower.endswith('brainmass.com'):
        value += 3.8
    return (doc, raw, previous, at_start, tail), float(value)

