"""Approximate a negative car/kar spelling-fragment detector, not a vehicle detector.

Short chunks are strongest, including a syllable completed across token boundaries.
Length, English word frequency, and capitalization modulate strength. Romanization
extends the rule across scripts. Short unspaced continuations retain a response.
There are explicit exceptions for Japanese 'card', Chinese ka-luo transliterations,
and a document-initial Title: label. These rules approximate, not reproduce, the
component's many smaller token-specific responses. Outside matches it predicts zero,
with a small negative document-start default.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
SYLLABLE = re.compile('[ck]ar')


@lru_cache(maxsize=8192)
def roman(text):
    # Preserve Arabic alif as a vowel; default transliteration omits it.
    return anyascii(text.replace('ا', 'a').replace('آ', 'a')).lower()


@lru_cache(maxsize=8192)
def frequency(text):
    return zipf_frequency(text, 'en')


def response(text, previous, older, position):
    if position == 1 and previous == 'Title' and text == ':':
        return -7.55
    if previous.endswith('卡') and text.startswith(('罗', '羅')):
        return -8.4
    if text == 'カード':
        return -2.2

    token = roman(text)
    prior = roman(older) + roman(previous)
    direct = SYLLABLE.search(token)
    joined = prior[-2:] + token
    boundary = len(prior[-2:])
    crossing = SYLLABLE.search(joined)
    if crossing and not (crossing.start() < boundary < crossing.end()):
        crossing = None

    if direct:
        suffix = sum(c.isalpha() for c in token[direct.end():])
        length = len(token)
        freq = frequency(re.sub('[^a-z]', '', token))
        if suffix == 0:
            if length > 4:
                return -0.12
            if direct.group().startswith('k'):
                return -4.6
            return -4.5 if length <= 3 else -3.0
        if length <= 5:
            if freq > 5.3:
                return -0.53
            if not text.isascii():
                return -2.0 if freq <= 3.5 else -0.04
            return -2.1
        return -0.76 if length <= 7 else -0.19

    if crossing:
        suffix = sum(c.isalpha() for c in joined[crossing.end():])
        freq = frequency(token)
        if suffix <= 1:
            if freq > 5.3:
                return -2.6
            return -3.6 if text[:1].isupper() else -5.5
        if freq <= 2.9:
            return -1.1 if freq <= 1.3 else -3.8
        return -0.62

    # An unspaced continuation can still belong to the car/kar fragment.
    matches = list(SYLLABLE.finditer(prior[-12:]))
    if matches and token[:1].isalpha():
        tail = prior[-12:][matches[-1].end():]
        if not re.search('[^a-z]', tail):
            distance = len(tail) + len(token)
            if distance <= 2:
                return -2.5 if roman(previous).endswith(('car', 'kar')) else -0.77
            return -0.67 if distance <= 3 else -0.11
    return -0.12 if position == 0 else 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        older, previous, position = '', '', 0
    else:
        _, older, previous, position = carry
    text = prefix.token_strings[-1]
    value = response(text, previous, older, position)
    return (document, previous, text, position + 1), float(value)

"""Approximate a mixed syntax-landmark feature, not general code detection.

Source-file opening keywords/comments receive strong negative pulses.
Loop membership, import namespaces, null comparisons, file/path words,
file-opening calls and shell arguments receive positive pulses. Doubled
backslashes are positive in likely TeX, negative in escaped code strings.
There are also initial Title-colon and repeated-middle-dot formatting rules.
Constants summarize training observations; unrecognized tokens predict zero.
Keep only 256 preceding characters and reset at each document boundary.
"""
import re
import sys

READS = ()

# Reserved words at the beginning of a source file (not in its body).
OPENING = {
    'function': -26.92,
    'var': -23.73,
    'const': -14.39,
    'class': -13.12,
    'type': -12.78,
    'def': -7.58,
    'int': -8.80,
    'char': -9.10,
    'val': -9.54,
    'module': -8.45,
    'namespace': -8.08,
    'string': -7.19,
    'package': -5.80,
    'import': -2.40,
    'from': -1.95,
    'using': -1.10,
    'export': -3.1,
}
# Shell utilities whose single-letter switches are recognized below.
SHELL = (
    r'(?:cat|grep|python\d?|ssh-[a-z-]+|pip\d?|git|curl|wget|find|ls|'
    r'sed|awk|sort|head|tail|cargo|go|npm|bash|sh|rustc|gcc|g\+\+|'
    r'ffmpeg|chown|chmod|make)'
)
# Ignore n/r/t escape continuations, except familiar TeX commands.
TEX = (
    r'\\(?:[a-mo-qsu-zA-Z][A-Za-z]+|text|times|theta|tau|to|tilde|'
    r'nabla|neq|nu|nonumber|right|rm)\b'
)


def predict(token, before, position):
    word = token.strip()
    previous = before.rstrip()
    if position == 0:
        if token == '<|endoftext|>':
            return -2.77
        if token in OPENING:
            return OPENING[token]
        if token == '(function':
            return -13.15
        if token == '//':
            return -9.2
        if token.startswith('//'):
            return -1.9 if '\n' in token else -3.66
        if token.startswith('/*'):
            if '\n' in token or len(token) > 8:
                return -2.8
            return -9.3 if token == '/**' else -6.1
        if token == '--':
            return -4.74
        if token.startswith('#include'):
            return -1.75
        if token.startswith(('"""', "'''")):
            return -2.6 if '\n' in token else -4.7
        if token == 'cd':
            return -1.36
    if token == '··' and not before.strip('·'):
        return -3.49
    if token == ':' and previous == 'Title' and position == 1:
        return 6.46

    # Normalize escaped newlines only for recognizing a line of source code.
    line = before.replace('\\n', '\n').replace('\\t', ' ').split('\n')[-1]
    if token in {' in', ' of', ' :'}:
        loop = re.search(r'\b(for|foreach)\b\s*(\(?[^\n;:=]{1,55})$', line)
        if loop:
            variables = loop[2]
            lead = line[:loop.start()]
            code = (not lead.strip(' \t0123456789:+-#')
                    or variables.lstrip().startswith('(')
                    or any(c in lead for c in '[{=}'))
            declaration = re.fullmatch(
                r'\(?\s*(?:(?:const|let|var|int|char|[A-Z]\w*)\s+)?'
                r'[&*]?\w+(?:\s*,\s*[&*]?\w+)*\s*\)?\s*', variables)
            if token == ' of' and not re.search(r'\b(const|let|var)\b', variables):
                code = False
            if code and declaration:
                return 1.35
        if token == ' in' and re.search(r'\bif\s+\w+\s*$', line):
            return 0.65
    if token == 'in':
        if previous.endswith('\\<'):
            return 1.0
        if previous.endswith('\\') and not previous.endswith('^\\'):
            return 0.6
    if token == ' ∈':
        return 0.5
    if token == ' range' and previous.endswith(':='):
        return 1.25
    if word in {'null', 'nil'} and re.search(r'(?<![=!])(?:==|!=)\s*$', before):
        return 1.05
    if word == 'open' and re.search(r'\bwith\s*$', line):
        return 1.9
    if token.startswith('(') and any(q in token for q in "\"'"):
        if re.search(r'\b(open|read_csv|read_excel|readFileSync|savefig)\s*$', before):
            return 1.6
    if token == ' {' and re.search(r'\bimport\s*$', line):
        return 1.05
    if token == '::' and re.search(r'\buse\s+[\w:]+$', line):
        return 0.8
    if token.startswith('.') and token[1:].islower():
        if re.search(r'\bimport\s+java$', line.rstrip()):
            return 2.65 if token == '.io' else 2.1
        if re.search(r'\bimport\s+android$', line.rstrip()):
            return 1.5
        if token == '.com' and previous.endswith('github'):
            return 1.55
        if token == '.path' and previous.endswith('os'):
            return 0.95
    if word in sys.stdlib_module_names and re.search(r'\bimport\s*$', line):
        return 0.9
    name = word.strip('_').lower()
    if name in {'path', 'file', 'dir', 'directory'}:
        if token.startswith('_'):
            return 0.55
        if token[:1].isspace():
            return 0.2
        return {'path': 0.55, 'file': 0.2, 'dir': 0.8, 'directory': 0.3}[name]
    if word == 'cd':
        return 0.9
    if word == 'cat' and (token == 'cat'
                          or previous.endswith(('&&', ';', 'sudo'))):
        return 0.65
    if (len(token) == 1 and token.isascii() and token.isalpha()
            and re.search(r'\b' + SHELL + r'[^\n;]{0,240} -$', before)):
        return 1.15
    if (word in {'build', 'run', 'test', 'check'}
            and re.search(r'\b(cargo|go|npm|yarn)\s*$', line)):
        return 1.05
    if (word in {'install', 'update', 'remove'}
            and re.search(r'\b(apt(?:-get)?|pip\d?|npm|yarn)\s*$', line)):
        return 1.15
    if (word in {'restore', 'checkout', 'status', 'diff', 'add', 'commit'}
            and re.search(r'\bgit\s*$', line)):
        return 0.8
    if word == '>' and re.search(r'\b(cat|echo)\b', before[-80:]):
        return 1.0
    if re.search(r'\\{2,}', token):
        return 1.25 if re.search(TEX, before) else -1.15
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', 0)
    _, before, position = carry
    token = prefix.token_strings[-1]
    value = predict(token, before, position)
    return (document, (before + token)[-256:], position + 1), value

"""Approximate responses to dates, times, fractions and other number suffixes.

Month units have the strongest negative signal. Colons and slashes after
short numbers are weaker; clock/date wording strengthens them, while code
identifiers, long numbers, indexing and later separators weaken them.
Smaller signals cover floors, days/ages and English ordinal endings.
The state is just a short text suffix, reset at document boundaries.
"""
import re

READS = ()
MONTHS = {'月', '月份', '월'}
FLOORS = {'楼', '樓'}
HOURS = {'時', '點', '시'}
DAYS_AGES = {'日', '歳', '岁', '歲'}
ORDINALS = {'th', 'nd', 'st', 'rd'}
UNITS = MONTHS | FLOORS | HOURS | DAYS_AGES | ORDINALS
NUMERAL = re.compile(r'(\d+|[一二三四五六七八九十两兩〇零]+)$')
CLOCK = re.compile(
    r'\b(?:at|around|time\s*[:：]?|until|after|before)\s*$|'
    r'(?:上午|下午|早上|中午|晚上|凌晨|时间[：:]?|時間[：:]?)\s*$', re.I)
DATE = re.compile(
    r'(?:date\s*:?|filed(?:\s+on)?|posted(?:\s+on)?|updated|dated|due|'
    r'\bon|monday|tuesday|wednesday|thursday|friday|saturday|sunday)\s*$', re.I)
RECENT_CLOCK = re.compile(r'\b(?:[01]?\d|2[0-3]):[0-5]\d\b')
RECENT_DATE = re.compile(r'\b\d{1,2}/\d{1,2}/\d{2,4}\b')


def predict(before, token):
    if token not in UNITS and token not in {':', '/', '：'}:
        return 0.0
    m = NUMERAL.search(before.rstrip(' ') if token in UNITS else before)
    if token in MONTHS:
        if not m:
            return 0.6
        return -9.7 if m[0].isdecimal() else -5.5
    if not m:
        return 0.07 if token == '/' else 0.03 if token == ':' else 0.0
    digits = m[0]
    if token in FLOORS:
        return -6.3
    if token in HOURS:
        return -3.9 if token == '시' else -6.6
    if token in DAYS_AGES:
        return -0.5
    if token in ORDINALS:
        return -0.3 if digits.isdecimal() else 0.0
    if not digits.isdecimal():
        return 0.0

    preceding = before[:m.start()]
    last = preceding[-1:]
    colon = token in {':', '：'}
    # Digits embedded in names or version strings are not date/time fields.
    in_name = last and last.isascii() and (last.isalpha() or last == '_')
    if in_name or last == '.':
        return -0.15 if colon else 0.01
    if len(digits) > 2:
        return -0.16 if colon else -0.04
    n = int(digits)
    if colon:
        if CLOCK.search(preceding):
            return -6.9
        if last == ':':
            return -1.3
        if last in {'[', '(', '=', '/'}:
            return -0.8
        if n == 0:
            return -1.3
        if RECENT_CLOCK.search(preceding[-70:]):
            return -4.5
        if not preceding.strip() or last in {'\n', '#'}:
            return -1.4
        return -2.7 if n < 25 else -2.1
    if last == '/':
        return -2.6
    if last in {'(', '+', '=', '*'}:
        return -2.0
    if n == 0:
        return -0.3
    if n > 31:
        return -1.8
    if DATE.search(preceding) or RECENT_DATE.search(preceding[-70:]):
        # Month-sized first fields have the strongest date response.
        return -8.6 if n <= 12 else -5.5
    return -4.6 if len(digits) == 2 else -3.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-150:]), predict(before, token)

"""A detector for resemblance and relational modifiers.

The strongest negative responses are noun-like and noun-shaped endings;
other compound adjectives are weaker. Joined -ish, -less, -proof and -y
are treated as morphology only when English word classes support that
reading. Rarer constructions get somewhat stronger responses. Dictionary
context distinguishes productive Chinese/Japanese suffixes from lexical
words; color names are treated separately.
"""
import re
from functools import lru_cache
import wordnet
import cedict
import opencc
import regex
from wordfreq import zipf_frequency

READS = ()
RELATION = frozenset('''based related oriented centered centred driven
    inspired'''.split())
OTHER_RELATION = frozenset('''induced associated linked bound borne led guided
    filled covered containing powered separated sponsored dominated controlled
    assisted speaking resistant dependent independent specific'''.split())
PROPERTY = frozenset('friendly rich sized grade wide'.split())
COLORS = frozenset('''black white red green blue brown gray grey pink
    yellow purple orange'''.split())
FUNCTION_WORDS = frozenset('''a an the this that these those any every some
    what which one is are was were be been being
    as or and of for with by on in at to from into without between
    during after before than it its they them their we our you your
    he his she her do did does have has had'''.split())
MODIFIERS = frozenset('''based related inspired driven shaped shape style
    type free proof friendly resistant'''.split())
HAN_SUFFIXES = {
    '型': -2.4, '式': -1.6, '状': -1.5, '狀': -1.5, '形': -1.2,
    '类': -1.3, '類': -1.3, '系': -1.1, '级': -1.0, '級': -1.0,
    '风': -0.2, '風': -0.2, '性': -0.4, '化': -0.6,
    '色': -0.55, '用': -0.2,
}

@lru_cache(maxsize=16384)
def pos(word):
    return wordnet.parts_of_speech(word.lower())

@lru_cache(maxsize=16384)
def rarity(word):
    return max(0.0, 5.0 - zipf_frequency(word.lower(), 'en'))


CONVERTER = opencc.OpenCC('t2s')

@lru_cache(maxsize=4096)
def han_response(before, suffix):
    """Separate productive suffixes from lexical words such as 'ceremony'."""
    before = CONVERTER.convert(before)
    char = CONVERTER.convert(suffix)
    definitions = ()
    for n in (3, 2, 1):
        definitions = cedict.glosses(before[-n:] + char)
        if definitions:
            break
    if char in {'型', '式'}:
        if before[-1:].isnumeric():
            return -0.2
        if definitions:
            return -0.4
        if regex.search(r'[\p{Script=Han}\p{Script=Katakana}]$', before):
            return -3.0
    if char == '状' and not definitions:
        for n in (2, 1):
            for gloss in cedict.glosses(before[-n:]):
                first = gloss.split()[0].strip('();,').lower() if gloss else ''
                if first and wordnet.is_a(first, 'object'):
                    return -6.0
    if char == '色':
        words = set(re.findall(r'[a-z]+', ' '.join(definitions).lower()))
        if words & (COLORS | {'silver', 'gold'}):
            return -2.5
        return -0.2
    if char == '用' and regex.search(r'\p{Script=Katakana}$', before):
        return -2.5
    return HAN_SUFFIXES[suffix]


def response(history, text):
    s = text.strip().lower()
    match = re.search(r'([A-Za-z]+)$', history)
    stem = match.group(1) if match else ''
    hyphen = s.startswith('-') and s[1:].isalpha()
    if history.endswith(('-', '‐', '‑')) and s.isalpha():
        hyphen = True
        match = re.search(r'([A-Za-z]+)[-‐‑]$', history)
        stem = match.group(1) if match else ''
    tail = s.lstrip('-')
    if hyphen:
        # Content-Type headers and markup attributes are not resemblance.
        markup = re.search(r'[={}_/\\]([^\s]*\s?){0,2}$', history[-40:])
        attribute = bool(markup) or stem.lower() == 'content'
        if tail in {'type', 'style', 'form'} and attribute:
            return 0.0
        if tail == 'like':
            return -8.7
        if tail == 'shaped':
            return -0.5 if stem and pos(stem) == {'adjective'} else -7.0
        if tail == 'type':
            return -5.0
        if tail in {'style', 'wise', 'ish'}:
            return -2.4
        if tail == 'form':
            return -1.2
        if tail == 'free':
            return -1.6 - 0.6 * rarity(stem) if stem else -2.2
        if tail in RELATION:
            return -2.4
        if tail in OTHER_RELATION or tail in PROPERTY:
            return -1.4
        if tail.endswith(('ed', 'ing')):
            return -0.3 - 0.2 * rarity(stem) if stem else -0.3
    joined = bool(stem) and not text[:1].isspace() and s.isalpha()
    if joined:
        word = (stem + s).lower()
        if s == 'based' and len(stem) > 1:
            return -2.2
        for ending in ('like', 'ish', 'less', 'proof'):
            if not word.endswith(ending) or len(s) > len(ending):
                continue
            root = word[:-len(ending)]
            if len(root) < 2 or root in {'un', 'dis', 'mis'}:
                continue
            if ending == 'ish' and (root in COLORS or root + 'e' in COLORS):
                return -5.8
            if 'noun' in pos(root) or 'adjective' in pos(word):
                if ending == 'like':
                    return -5.5
                if ending == 'proof':
                    return -3.5
                if ending == 'less':
                    return -0.4 * rarity(word)
                return -0.6 - 0.45 * rarity(word)
        if s == 'oid':
            return -0.85
        if s == 'y' and 'adjective' in pos(word):
            return -0.3 * rarity(word)
        if s in {'ized', 'ised'}:
            return -0.4
    if s in HAN_SUFFIXES:
        return han_response(history[-4:], s)
    if s in MODIFIERS:
        if text.strip() == 'Type':
            return 0.18
        previous = re.search(r'([A-Za-z]+)\s+$', history)
        left = stem if text[:1].isspace() else ''
        if not left and previous:
            left = previous.group(1)
        if left.lower() not in FUNCTION_WORDS and len(left) > 1:
            if 'noun' in pos(left) or left.istitle():
                return -0.5 - 0.55 * rarity(left + ' ' + s)
        return -0.2 if s == 'style' else 0.0
    return 0.18 if s == 'like' else -0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = ''
    if carry is not None and carry[0] == doc:
        history = carry[1]
    text = prefix.token_strings[-1]
    value = response(history, text)
    return (doc, (history + text)[-80:]), float(value)
